import {
  createInspectorCatalog,
  type InspectorField,
  type SelectInspectorField,
} from "../shared/inspectorCatalog";
import { resetInspectorValues, type Rgba, type Scene } from "../shared/sceneSchema";
import { type MugMetadata } from "../shared/luaCompletionContext";
import { applyHexToRgb, clampUnit, rgbaToHex } from "../core/color";
import { stepNumericText } from "../core/numericInput";
import { inspectorPages, type InspectorPage } from "../shared/simulatorPages";
import type { SystemFontEntry } from "../shared/messages";

export interface InspectorFontOptions {
  fonts: readonly SystemFontEntry[];
  onSelected: (path: string) => void;
  onBrowse: () => void;
}

const kDefaultFontOptions: InspectorFontOptions = {
  fonts: [],
  onSelected: () => undefined,
  onBrowse: () => undefined,
};

// Generic renderer for the declarative inspector catalog. Host inspector
// changes should require catalog edits, not new DOM code here.
export class Inspector {
  private readonly inspector: HTMLElement;
  private characterCount: number;
  private partCount: number;
  private selectedPage: InspectorPage = "simulator";
  private readonly sectionOpenStates = new Map<string, boolean>();
  private currentMetadata?: MugMetadata;

  constructor(
    container: HTMLElement,
    scene: Scene,
    characterCount: number,
    partCount: number,
    private readonly onChanged: () => void,
    private readonly fontOptions: InspectorFontOptions = kDefaultFontOptions,
    private readonly onClose?: () => void,
    metadata?: MugMetadata,
  ) {
    this.characterCount = characterCount;
    this.partCount = partCount;
    this.currentMetadata = metadata;
    this.inspector = document.createElement("aside");
    this.inspector.className = "inspector";
    container.appendChild(this.inspector);
    this.refresh(scene, characterCount, partCount, metadata);
  }

  updateMetadata(metadata: MugMetadata | undefined): void {
    this.currentMetadata = metadata;
  }

  refresh(scene: Scene, characterCount: number, partCount: number, metadata?: MugMetadata): void {
    if (metadata !== undefined) {
      this.currentMetadata = metadata;
    }
    this.characterCount = characterCount;
    this.partCount = partCount;
    const focused = this.captureFocus();
    for (const section of this.inspector.querySelectorAll<HTMLDetailsElement>("details[data-section-title]")) {
      const sectionTitle = section.dataset.sectionTitle;
      if (sectionTitle !== undefined) {
        this.sectionOpenStates.set(sectionTitle, section.open);
      }
    }
    this.inspector.replaceChildren();

    const header = document.createElement("header");
    header.className = "inspector-header";

    const leftGroup = document.createElement("div");
    leftGroup.style.display = "flex";
    leftGroup.style.alignItems = "center";
    leftGroup.style.gap = "6px";

    if (this.onClose !== undefined) {
      const closeButton = document.createElement("button");
      closeButton.type = "button";
      closeButton.className = "inspector-close-button";
      closeButton.title = "Collapse Inspector";
      closeButton.textContent = "";
      closeButton.addEventListener("click", () => {
        this.onClose?.();
      });
      leftGroup.appendChild(closeButton);
    }

    const title = document.createElement("strong");
    title.textContent = "Inspector";
    leftGroup.appendChild(title);

    const resetButton = document.createElement("button");
    resetButton.type = "button";
    resetButton.title = "Reset all inspector values";
    resetButton.textContent = "↺ Reset";
    resetButton.addEventListener("click", () => {
      resetInspectorValues(scene, this.currentMetadata);
      this.onChanged();
      this.refresh(scene, this.characterCount, this.partCount);
    });

    header.append(leftGroup, resetButton);
    this.inspector.appendChild(header);

    const tabs = document.createElement("div");
    tabs.className = "panel-tabs inspector-tabs";
    tabs.role = "tablist";
    for (const page of inspectorPages) {
      const button = document.createElement("button");
      button.type = "button";
      button.role = "tab";
      button.textContent = page.label;
      button.title = page.title;
      button.className = "panel-tab";
      button.classList.toggle("panel-tab-active", page.id === this.selectedPage);
      button.setAttribute("aria-selected", String(page.id === this.selectedPage));
      button.addEventListener("click", () => {
        if (this.selectedPage !== page.id) {
          this.selectedPage = page.id;
          this.refresh(scene, this.characterCount, this.partCount);
        }
      });
      tabs.appendChild(button);
    }
    this.inspector.appendChild(tabs);

    const sections = createInspectorCatalog(scene, characterCount, partCount).filter(
      (section) => section.page === this.selectedPage,
    );
    for (const sectionDefinition of sections) {
      const section = document.createElement("details");
      section.dataset.sectionTitle = sectionDefinition.title;
      section.open =
        this.sectionOpenStates.get(sectionDefinition.title) ??
        (sectionDefinition.initiallyOpen ?? false);
      const summary = document.createElement("summary");
      summary.textContent = sectionDefinition.title;
      const fields = document.createElement("div");
      fields.className = "inspector-fields";
      for (const field of sectionDefinition.fields) {
        fields.append(this.makeLabel(field.label), this.makeControl(field, scene, this.onChanged));
      }
      section.append(summary, fields);
      this.inspector.appendChild(section);
    }
    this.restoreFocus(focused);
  }

  private makeControl(field: InspectorField, scene: Scene, onChanged: () => void): HTMLElement {
    let result: HTMLElement;
    switch (field.kind) {
      case "number": {
        const input = document.createElement("input");
        input.type = "text";
        input.inputMode = "decimal";
        input.value = String(field.read(scene));
        input.addEventListener("keydown", (event) => {
          if (event.key === "ArrowUp" || event.key === "ArrowDown") {
            const direction = event.key === "ArrowUp" ? 1 : -1;
            const stepped = stepNumericText(
              input.value,
              input.selectionStart ?? input.value.length,
              direction,
              field.step,
            );
            if (stepped !== undefined) {
              event.preventDefault();
              field.write(scene, stepped.value);
              const normalizedValue = field.read(scene);
              input.value = Object.is(normalizedValue, stepped.value)
                ? stepped.text
                : String(normalizedValue);
              const caret = Math.min(stepped.caret, input.value.length);
              input.setSelectionRange(caret, caret);
              onChanged();
            }
          }
        });
        input.addEventListener("change", () => {
          const parsed = Number(input.value);
          if (Number.isFinite(parsed)) {
            field.write(scene, parsed);
            input.value = String(field.read(scene));
            onChanged();
          }
        });
        result = input;
        break;
      }
      case "text": {
        const input = field.multiline
          ? document.createElement("textarea")
          : document.createElement("input");
        input.value = field.read(scene);
        let composing = false;
        let notifiedValue = input.value;
        const notifyChanged = (): void => {
          field.write(scene, input.value);
          if (input.value !== notifiedValue) {
            notifiedValue = input.value;
            onChanged();
          }
        };
        input.addEventListener("compositionstart", () => {
          composing = true;
        });
        input.addEventListener("compositionend", () => {
          composing = false;
        });
        input.addEventListener("input", (event) => {
          field.write(scene, input.value);
          if (!composing && !(event as InputEvent).isComposing) {
            notifyChanged();
          }
        });
        input.addEventListener("change", () => {
          if (!composing) {
            notifyChanged();
          }
        });
        result = input;
        break;
      }
      case "boolean": {
        const input = document.createElement("input");
        input.type = "checkbox";
        input.checked = field.read(scene);
        input.addEventListener("change", () => {
          field.write(scene, input.checked);
          onChanged();
          this.refresh(scene, this.characterCount, this.partCount);
        });
        result = input;
        break;
      }
      case "select": {
        result = this.makeSelect(field, scene, onChanged);
        break;
      }
      case "font": {
        result = this.makeFontControl(scene);
        break;
      }
      case "color": {
        result = this.makeColorFields(field.read(scene), onChanged, field.showAlpha);
        break;
      }
    }
    result.dataset.inspectorPath = field.path;
    const enabled = field.enabled?.(scene) ?? true;
    result.classList.toggle("inspector-control-disabled", !enabled);
    if (
      result instanceof HTMLInputElement ||
      result instanceof HTMLSelectElement ||
      result instanceof HTMLTextAreaElement
    ) {
      result.disabled = !enabled;
    }
    for (const control of result.querySelectorAll<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(
      "input, select, textarea",
    )) {
      control.disabled = !enabled;
    }
    return result;
  }

  private captureFocus(): { path: string; start: number | null; end: number | null } | undefined {
    const active = document.activeElement;
    let result: { path: string; start: number | null; end: number | null } | undefined;
    if (active instanceof HTMLInputElement || active instanceof HTMLTextAreaElement) {
      const path = active.dataset.inspectorPath;
      if (path !== undefined) {
        result = { path, start: active.selectionStart, end: active.selectionEnd };
      }
    } else if (active instanceof HTMLSelectElement) {
      const path = active.dataset.inspectorPath;
      if (path !== undefined) {
        result = { path, start: null, end: null };
      }
    }
    return result;
  }

  private restoreFocus(
    focused: { path: string; start: number | null; end: number | null } | undefined,
  ): void {
    if (focused === undefined) {
      return;
    }
    const control = [...this.inspector.querySelectorAll<HTMLElement>("[data-inspector-path]")].find(
      (candidate) => candidate.dataset.inspectorPath === focused.path,
    );
    control?.focus();
    if (
      focused.start !== null &&
      focused.end !== null &&
      (control instanceof HTMLInputElement || control instanceof HTMLTextAreaElement)
    ) {
      control.setSelectionRange(focused.start, focused.end);
    }
  }

  private makeSelect(
    field: SelectInspectorField,
    scene: Scene,
    onChanged: () => void,
  ): HTMLSelectElement {
    const select = document.createElement("select");
    for (const [optionValue, optionLabel] of field.options) {
      const option = document.createElement("option");
      option.value = optionValue;
      option.textContent = optionLabel;
      select.appendChild(option);
    }
    select.value = field.read(scene);
    select.addEventListener("change", () => {
      field.write(scene, select.value);
      onChanged();
      this.refresh(scene, this.characterCount, this.partCount);
    });
    return select;
  }

  private makeColorFields(color: Rgba, onChanged: () => void, showAlpha: boolean): HTMLElement {
    const fields = document.createElement("div");
    fields.className = "color-fields";
    const picker = document.createElement("input");
    picker.type = "color";
    picker.title = "RGB color";
    picker.value = rgbaToHex(color);
    picker.addEventListener("input", () => {
      applyHexToRgb(picker.value, color);
      onChanged();
    });

    const alpha = document.createElement("input");
    alpha.type = "number";
    alpha.min = "0";
    alpha.max = "1";
    alpha.step = "0.01";
    alpha.title = "Alpha";
    alpha.value = String(color.a);
    alpha.addEventListener("change", () => {
      const parsed = Number(alpha.value);
      if (Number.isFinite(parsed)) {
        color.a = clampUnit(parsed);
        alpha.value = String(color.a);
        onChanged();
      }
    });
    fields.append(picker);
    if (showAlpha) {
      fields.append(alpha);
    }
    return fields;
  }

  private makeFontControl(scene: Scene): HTMLElement {
    const fields = document.createElement("div");
    fields.className = "font-fields";
    const select = document.createElement("select");
    select.title = "Font";
    for (const font of this.fontOptions.fonts) {
      const option = document.createElement("option");
      option.value = font.path;
      option.textContent = font.label;
      option.title = `${font.family} — ${font.style}\n${font.path}`;
      select.appendChild(option);
    }
    const selectedPath = scene.settings.fontPath;
    if (selectedPath !== undefined && !this.fontOptions.fonts.some((font) => font.path === selectedPath)) {
      const option = document.createElement("option");
      option.value = selectedPath;
      option.textContent = fontFileName(selectedPath);
      select.appendChild(option);
    }
    if (selectedPath !== undefined) {
      select.value = selectedPath;
    } else if (scene.global.fontName.length > 0) {
      const matchingFont = this.fontOptions.fonts.find((font) => font.family === scene.global.fontName);
      if (matchingFont !== undefined) {
        select.value = matchingFont.path;
      }
    }
    select.addEventListener("change", () => this.fontOptions.onSelected(select.value));

    const browseButton = document.createElement("button");
    browseButton.type = "button";
    browseButton.textContent = "Browse…";
    browseButton.title = "Choose a TTF, OTF, or TTC font outside the system catalog";
    browseButton.addEventListener("click", () => this.fontOptions.onBrowse());
    fields.append(select, browseButton);
    return fields;
  }

  private makeLabel(text: string): HTMLLabelElement {
    const label = document.createElement("label");
    label.textContent = text;
    return label;
  }
}

function fontFileName(path: string): string {
  const segments = path.split(/[\\/]/);
  return segments[segments.length - 1] || path;
}
