import type { LuaHookPhase } from "./scriptingApi";

export interface LuaHookInfo {
  name: string;
  phase: LuaHookPhase;
  /** Full function signature line for hover / detail. */
  signature: string;
  description: string;
  descriptionJa?: string;
  /** Body snippet inserted after `function Name(ctx)\n`. */
  bodyComment: string;
}

/**
 * Host-invoked global entry points. Names are PascalCase so typical LuaLS
 * lowercase-global diagnostics do not fire on the definitions.
 */
export const kLuaHooks: readonly LuaHookInfo[] = [
  {
    name: "OnInitialize",
    phase: "initialize",
    signature: "function OnInitialize(ctx)",
    description:
      "Compatibility hook for existing scripts; do not use it in new scripts. " +
      "Initialize constants in locals declared outside functions instead.",
    descriptionJa:
      "既存スクリプトとの互換性のためのコールバックです。新規スクリプトでは使用せず、" +
      "初期化処理と定数には関数の外側で宣言した local 変数を使用してください。",
    bodyComment: "-- Compatibility hook for existing scripts.",
  },
  {
    name: "OnPreLayout",
    phase: "pre_layout",
    signature: "function OnPreLayout(ctx)",
    description:
      "Called every frame before layout generation. " +
      "Read/write Base inputs on `ctx.global` and `ctx.camera`. " +
      "`ctx.char_count` / `ctx.part_count` are not defined yet; use `utf8.len(ctx.global.text)` for length estimates. " +
      "Read and rewrite text via `ctx.global.text`; `ctx.text` is deprecated.",
    descriptionJa:
      "レイアウト生成前（毎フレーム）に呼ばれます。" +
      "`ctx.global` および `ctx.camera` の全体パラメータ（Base）を読み書きして調整します。" +
      "`ctx.char_count` や `ctx.part_count` はまだ未定義です（テキスト変更は `ctx.global.text` へ代入）。",
    bodyComment: "-- Adjust ctx.global / ctx.camera before layout.",
  },
  {
    name: "OnLayout",
    phase: "layout",
    signature: "function OnLayout(ctx)",
    description:
      "Called every frame after layout generation. " +
      "Adjust per-character and per-part values (`ctx.chars`, `ctx.parts`), plus `ctx.bounding_box` / `ctx.output`. " +
      "`ctx.global` / `ctx.camera` are read-only confirmed Base values. " +
      "`ctx.char_count` / `ctx.part_count` are defined.",
    descriptionJa:
      "レイアウト生成後（毎フレーム）に呼ばれます。" +
      "生成された文字 (`ctx.chars`) やパーツ (`ctx.parts`)、`bounding_box` や `output` を個別に調整します。" +
      "`ctx.global` / `ctx.camera` は確定値（読み取り専用）として参照できます。",
    bodyComment: "-- Adjust ctx.chars / ctx.parts after layout.",
  },
  {
    name: "OnPath",
    phase: "path",
    signature: "function OnPath(ctx)",
    description:
      "Called every frame after OnLayout. Select only the outlines you need through `ctx.paths`. " +
      "Replace or rebuild each selected part's normalized path. " +
      "Each entry exposes global, character, per-character, and line indices.",
    descriptionJa:
      "OnLayout の後に毎フレーム呼ばれ、`ctx.paths` から必要な輪郭だけを選択します。" +
      "選択パーツの正規化パスを置換または再構築できます。" +
      "各要素から通し番号、文字番号、文字内番号、行番号を参照できます。",
    bodyComment: "-- Select and replace normalized outlines through ctx.paths.",
  },
];

export function findLuaHook(name: string): LuaHookInfo | undefined {
  return kLuaHooks.find((hook) => hook.name === name);
}

export function getLuaHookDescription(hook: LuaHookInfo, isJapanese: boolean): string {
  const description = isJapanese && hook.descriptionJa !== undefined ? hook.descriptionJa : hook.description;
  return description;
}
