import type {
  BaseHookData,
  CtxCharacterData,
  CtxPartData,
  InitializeHookData,
  LayoutHookData,
} from "./ctxBindings";
import type { ScriptEngine } from "./luaEngine";

export interface ScriptHookEvaluation<Data> {
  data: Data;
  succeeded: boolean;
  errors: string[];
  warnings: string[];
}

export interface PathPartHookData {
  index: number;
  character_index: number;
  index_in_character: number;
  line_index: number;
  text: string;
  path: { svg: string; units_per_em: number; em_scale?: number; view_box?: number[] };
  edited?: boolean;
}

export interface PathHookData extends Omit<LayoutHookData, "text"> {
  path_parts: PathPartHookData[];
}

export class ScriptFramePipeline {
  constructor(private readonly engine: ScriptEngine) {}

  initialize(data: InitializeHookData): { errors: string[]; storage?: unknown } {
    const result = this.engine.runInitialize(data);
    const errors = result.ok ? [] : [`OnInitialize: ${result.message ?? "unknown error"}`];
    return { errors, storage: result.storage };
  }

  evaluateBase(data: BaseHookData, seed: number): ScriptHookEvaluation<BaseHookData> {
    const result = this.engine.callHook("OnPreLayout", "pre_layout", data, seed);
    const evaluated = result.ok && result.data !== undefined
      ? result.data as BaseHookData
      : data;
    return {
      data: evaluated,
      succeeded: result.ok,
      errors: hookErrors("OnPreLayout", result.ok, result.message),
      warnings: globalWriteWarnings("OnPreLayout", result.globalWrites),
    };
  }

  evaluateLayout(data: LayoutHookData, seed: number): ScriptHookEvaluation<LayoutHookData> {
    const result = this.engine.callHook("OnLayout", "layout", data, seed);
    let evaluated = data;
    if (result.ok && result.data !== undefined) {
      const returned = result.data as LayoutHookResultData;
      evaluated = {
        ...returned,
        chars: normalizeArray(returned.chars),
        parts: normalizeArray(returned.parts),
      };
    }
    return {
      data: evaluated,
      succeeded: result.ok,
      errors: hookErrors("OnLayout", result.ok, result.message),
      warnings: globalWriteWarnings("OnLayout", result.globalWrites),
    };
  }

  evaluatePaths(data: PathHookData, seed: number): ScriptHookEvaluation<PathHookData> {
    const result = this.engine.callHook("OnPath", "path", data, seed);
    let evaluated = data;
    if (result.ok && result.data !== undefined) {
      const returned = result.data as Omit<PathHookData, "path_parts"> & {
        path_parts: PathPartHookData[] | Record<string, PathPartHookData>;
      };
      evaluated = { ...returned, path_parts: normalizeArray(returned.path_parts) };
    }
    return {
      data: evaluated,
      succeeded: result.ok,
      errors: hookErrors("OnPath", result.ok, result.message),
      warnings: globalWriteWarnings("OnPath", result.globalWrites),
    };
  }
}

type LayoutHookResultData = Omit<LayoutHookData, "chars" | "parts"> & {
  chars: CtxCharacterData[] | Record<string, CtxCharacterData>;
  parts: CtxPartData[] | Record<string, CtxPartData>;
};

function hookErrors(hookName: string, succeeded: boolean, message: string | undefined): string[] {
  return succeeded ? [] : [`${hookName}: ${message ?? "unknown error"}`];
}

function globalWriteWarnings(hookName: string, globalWrites: string[]): string[] {
  return globalWrites.map(
    (name) =>
      `${hookName}: global variable '${name}' was written inside a hook — ` +
      "hooks must stay stateless (results may differ between scrub and render)",
  );
}

// wasmoon returns Lua arrays as JS arrays, but an empty Lua table comes back
// as a plain object; normalize so downstream code can always index.
function normalizeArray<T>(value: T[] | Record<string, T>): T[] {
  return Array.isArray(value) ? value : Object.values(value ?? {});
}
