import type { EvaluatedFrame } from "../core/frameEvaluator";
import { renderFrame } from "../core/renderer";
import type { DisplayMode } from "../shared/sceneSchema";

const kMimeTypeCandidates = [
  "video/webm;codecs=vp9",
  "video/webm;codecs=vp8",
  "video/webm",
];

// Records evaluated frames into a WebM blob. Frames are mirrored onto an
// offscreen canvas at the scene's native pixel size, so the output resolution
// is independent of the preview panel size and zoom. Capture is push-driven
// (captureStream(0) + requestFrame) with wall-clock timestamps, matching the
// realtime playback that drives it.
export class VideoRecorder {
  private readonly context: CanvasRenderingContext2D;
  private readonly track: CanvasCaptureMediaStreamTrack;
  private readonly recorder: MediaRecorder;
  private readonly chunks: Blob[] = [];

  constructor(canvasWidth: number, canvasHeight: number) {
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(Math.round(canvasWidth), 1);
    canvas.height = Math.max(Math.round(canvasHeight), 1);
    const context = canvas.getContext("2d");
    if (context === null) {
      throw new Error("2D canvas context unavailable for recording");
    }
    this.context = context;
    const stream = canvas.captureStream(0);
    this.track = stream.getVideoTracks()[0] as CanvasCaptureMediaStreamTrack;
    const mimeType = kMimeTypeCandidates.find((candidate) =>
      MediaRecorder.isTypeSupported(candidate),
    );
    if (mimeType === undefined) {
      throw new Error("WebM recording is not supported in this webview");
    }
    this.recorder = new MediaRecorder(stream, { mimeType });
    this.recorder.addEventListener("dataavailable", (event) => {
      if (event.data.size > 0) {
        this.chunks.push(event.data);
      }
    });
    this.recorder.start();
  }

  captureFrame(frame: EvaluatedFrame, displayMode: DisplayMode, showIndexLabels: boolean): void {
    renderFrame(this.context, frame, 1, { displayMode, showIndexLabels });
    this.track.requestFrame();
  }

  stop(): Promise<Blob> {
    return new Promise((resolve, reject) => {
      this.recorder.addEventListener("stop", () => {
        this.track.stop();
        resolve(new Blob(this.chunks, { type: this.recorder.mimeType }));
      });
      this.recorder.addEventListener("error", (event) => {
        this.track.stop();
        reject(new Error(`recording failed: ${String(event)}`));
      });
      this.recorder.stop();
    });
  }
}
