import type { DisplayMode, PartMode } from "../shared/sceneSchema";

export interface ToolbarState {
  displayMode: DisplayMode;
  partMode: PartMode;
  partsPerCharacter: number;
}

export interface ToolbarCallbacks {
  onSettingsChanged: (state: ToolbarState) => void;
  onCopyScript?: () => void;
  onResetLayout?: () => void;
}

// Top bar with the simulator-level controls: font, display mode (glyph
// outline / box), part approximation mode.
export class Toolbar {
  private static readonly copyFeedbackDurationMilliseconds = 1500;

  private readonly bar: HTMLDivElement;
  private readonly displaySelect: HTMLSelectElement;
  private readonly partSelect: HTMLSelectElement;
  private readonly partCountInput: HTMLInputElement;
  private readonly topologyStatus: HTMLSpanElement;
  private readonly copyScriptButton: HTMLButtonElement | undefined;
  private copyFeedbackTimer: ReturnType<typeof setTimeout> | undefined;

  constructor(
    container: HTMLElement,
    private readonly state: ToolbarState,
    private readonly callbacks: ToolbarCallbacks,
  ) {
    this.bar = document.createElement("div");
    this.bar.className = "toolbar";

    this.displaySelect = document.createElement("select");
    this.displaySelect.title = "Display mode";
    appendOption(this.displaySelect, "glyph", "Glyph outline");
    appendOption(this.displaySelect, "box", "Boxes");
    this.displaySelect.value = state.displayMode;
    this.displaySelect.addEventListener("change", () => {
      this.state.displayMode = this.displaySelect.value as DisplayMode;
      this.notify();
    });

    this.partSelect = document.createElement("select");
    this.partSelect.title = "Part approximation";
    appendOption(this.partSelect, "contour", "Parts: contours");
    appendOption(this.partSelect, "fixed", "Parts: fixed count");
    this.partSelect.value = state.partMode;
    this.partSelect.addEventListener("change", () => {
      this.state.partMode = this.partSelect.value as PartMode;
      this.updatePartCountVisibility();
      this.notify();
    });

    this.partCountInput = document.createElement("input");
    this.partCountInput.type = "number";
    this.partCountInput.min = "1";
    this.partCountInput.max = "16";
    this.partCountInput.value = String(state.partsPerCharacter);
    this.partCountInput.title = "Parts per character";
    this.partCountInput.addEventListener("change", () => {
      const count = Math.max(1, Math.min(16, Number(this.partCountInput.value) || 1));
      this.partCountInput.value = String(count);
      this.state.partsPerCharacter = count;
      this.notify();
    });

    this.topologyStatus = document.createElement("span");
    this.topologyStatus.className = "topology-status";

    this.bar.append(
      this.displaySelect,
      this.partSelect,
      this.partCountInput,
    );

    if (this.callbacks.onCopyScript !== undefined) {
      this.copyScriptButton = document.createElement("button");
      this.copyScriptButton.type = "button";
      this.copyScriptButton.className = "toolbar-copy-script-button";
      this.copyScriptButton.title = "Copy the current Lua script to the clipboard";
      this.copyScriptButton.textContent = "Copy Script";
      this.copyScriptButton.addEventListener("click", () => {
        this.callbacks.onCopyScript?.();
      });
      this.bar.appendChild(this.copyScriptButton);
    }

    if (this.callbacks.onResetLayout !== undefined) {
      const resetUiButton = document.createElement("button");
      resetUiButton.type = "button";
      resetUiButton.className = "toolbar-reset-ui-button";
      resetUiButton.title = "Reset UI layout sizes and states";
      resetUiButton.textContent = "↺ Reset Layout";
      resetUiButton.addEventListener("click", () => {
        this.callbacks.onResetLayout?.();
      });
      this.bar.appendChild(resetUiButton);
    }

    this.bar.appendChild(this.topologyStatus);
    container.appendChild(this.bar);
    this.updatePartCountVisibility();
  }

  showCopyResult(success: boolean): void {
    if (this.copyScriptButton !== undefined) {
      if (this.copyFeedbackTimer !== undefined) {
        clearTimeout(this.copyFeedbackTimer);
      }
      this.copyScriptButton.classList.toggle("copy-succeeded", success);
      this.copyScriptButton.classList.toggle("copy-failed", !success);
      this.copyScriptButton.textContent = success ? "✓ Copied!" : "Copy Failed";
      this.copyFeedbackTimer = setTimeout(() => {
        this.copyScriptButton?.classList.remove("copy-succeeded", "copy-failed");
        if (this.copyScriptButton !== undefined) {
          this.copyScriptButton.textContent = "Copy Script";
        }
        this.copyFeedbackTimer = undefined;
      }, Toolbar.copyFeedbackDurationMilliseconds);
    }
  }

  addLeadingControl(control: HTMLElement): void {
    this.bar.prepend(control);
  }

  setTopology(characterCount: number, partCount: number): void {
    this.topologyStatus.textContent = `${characterCount} chars · ${partCount} parts`;
  }

  applyState(state: ToolbarState): void {
    this.state.displayMode = state.displayMode;
    this.displaySelect.value = state.displayMode;
    this.state.partMode = state.partMode;
    this.partSelect.value = state.partMode;
    this.state.partsPerCharacter = state.partsPerCharacter;
    this.partCountInput.value = String(state.partsPerCharacter);
    this.updatePartCountVisibility();
  }

  private updatePartCountVisibility(): void {
    this.partCountInput.style.display = this.state.partMode === "fixed" ? "" : "none";
  }

  private notify(): void {
    this.callbacks.onSettingsChanged(this.state);
  }
}

function appendOption(select: HTMLSelectElement, value: string, label: string): void {
  const option = document.createElement("option");
  option.value = value;
  option.textContent = label;
  select.appendChild(option);
}
