import type { SystemFontEntry } from "../../shared/messages";

// Bundled fonts ship as static assets under web/fonts/ (see esbuild.web.mjs).
// Their "path" doubles as the fetch URL relative to the built page.
//
// Both are OFL-licensed (see the *-OFL.txt files next to them). The Japanese
// font is a subset: upstream Noto Sans JP is a ~9.6MB variable font covering
// the full Han glyph set, so scripts/build-web-jp-font.sh pins it to Regular
// and to JIS X 0208 level 1+2 kanji, which fits in ~2.2MB. Characters outside
// that set (rare kanji, non-Japanese CJK) render as missing glyphs; users who
// need full coverage pick an installed font through the Local Font Access API
// (queryLocalFontEntries, Chromium-only).
export const bundledFontEntries: readonly SystemFontEntry[] = [
  { family: "Inter", style: "Regular", label: "Inter — Regular", path: "fonts/Inter-Variable.ttf" },
  {
    family: "Noto Sans JP",
    style: "Regular",
    label: "Noto Sans JP — Regular (JIS X 0208 subset)",
    path: "fonts/NotoSansJP-Subset.ttf",
  },
];

// The bundled font covering CJK, i.e. what `@recommend lang ja` (explicit or
// inferred from `@recommend text`) resolves to. Kept as a path rather than an
// index so reordering bundledFontEntries cannot silently repoint it.
export const kJapaneseBundledFontPath = "fonts/NotoSansJP-Subset.ttf";

// Picks the bundled font to seed a scene with for a script's font language.
// The web build only ships Latin and Japanese fonts, so anything that is not
// Japanese falls through to the caller's own default.
export function chooseBundledFontForLanguage(lang?: string): SystemFontEntry | undefined {
  const normalizedLang = lang?.toLowerCase();
  const wantsJapanese =
    normalizedLang === "ja" || normalizedLang === "ja-jp" || normalizedLang === "japanese";
  let result: SystemFontEntry | undefined;
  if (wantsJapanese) {
    result = bundledFontEntries.find((font) => font.path === kJapaneseBundledFontPath);
  }
  return result;
}

const kLocalFontPathPrefix = "local-font-access:";

export function isLocalFontAccessPath(path: string): boolean {
  return path.startsWith(kLocalFontPathPrefix);
}

function localFontAccessPath(postscriptName: string): string {
  return `${kLocalFontPathPrefix}${postscriptName}`;
}

// Chromium-only: prompts the user once, then lists their installed fonts.
// Each entry's "path" is a marker string (not a real path); loadFontBytes
// resolves it back to a FontData handle via queryLocalFonts() at fetch time.
export async function queryLocalFontEntries(): Promise<SystemFontEntry[]> {
  if (!("queryLocalFonts" in window)) {
    return [];
  }
  const fonts = await (window as unknown as { queryLocalFonts(): Promise<FontData[]> }).queryLocalFonts();
  return fonts.map((font) => ({
    family: font.family,
    style: font.style,
    label: `${font.family} — ${font.style}`,
    path: localFontAccessPath(font.postscriptName),
  }));
}

// Resolves a SystemFontEntry.path (bundled asset URL or local-font-access
// marker) to font bytes.
export async function loadFontBytes(path: string): Promise<ArrayBuffer> {
  let result: ArrayBuffer;
  if (isLocalFontAccessPath(path)) {
    const postscriptName = path.slice(kLocalFontPathPrefix.length);
    const fonts = await (window as unknown as { queryLocalFonts(): Promise<FontData[]> }).queryLocalFonts();
    const match = fonts.find((font) => font.postscriptName === postscriptName);
    if (match === undefined) {
      throw new Error(`local font no longer available: ${postscriptName}`);
    }
    const blob = await match.blob();
    result = await blob.arrayBuffer();
  } else {
    const response = await fetch(path);
    if (!response.ok) {
      throw new Error(`failed to fetch font asset: ${path} (${response.status})`);
    }
    result = await response.arrayBuffer();
  }
  return result;
}

// Minimal ambient type for the Local Font Access API (not yet in lib.dom.d.ts
// across all TS/lib target combinations this project supports).
interface FontData {
  family: string;
  style: string;
  postscriptName: string;
  blob(): Promise<Blob>;
}
