import { LuaEngine, LuaFactory } from "wasmoon";
import { makeLuaDiagnosticsChunk } from "./luaDiagnostics";
import { kInternalsChunk, kSandboxChunk } from "./luaInternals";

export interface ScriptEngineOptions {
  // URI of wasmoon's glue.wasm. Omit in node (resolved from node_modules);
  // required in the webview where the wasm ships as an extension asset.
  wasmUri?: string;
  preludeSource: string;
  log: (text: string) => void;
}

// The host plugin implements mt.svg_path in C++ and embeds prelude.lua alone, so
// the pure-Lua stand-in lives in a separate file that only the simulator loads.
// Every simulator entry point joins the two here to keep preludeSource a single
// string across the webview message and diagnostics paths.
export function joinPreludeSources(
  preludeSource: string,
  drawingPathSource: string,
): string {
  return `${preludeSource}\n${drawingPathSource}`;
}

export interface HookResult {
  ok: boolean;
  message?: string;
  globalWrites: string[];
  // The data table after the hook ran (deep copy back from Lua). Undefined
  // when the hook errored: per the error policy the frame falls back to the
  // unmodified input values.
  data?: unknown;
}

interface RawHookResult {
  ok: boolean;
  message?: string;
  global_writes?: Record<string, string>;
  data?: unknown;
}

interface RawLoadResult {
  ok: boolean;
  message?: string;
}

interface InternalApi {
  loadChunk: (source: string, chunkName: string) => RawLoadResult;
  callHook: (hookName: string, data: unknown, phase: string, seed?: number) => RawHookResult;
  hasHook: (hookName: string) => boolean;
  clearHooks: () => void;
  beginInitialize: (seed: number) => void;
  finishInitialize: () => void;
  storageSnapshot: () => unknown;
}

interface LuaRuntime {
  lua: LuaEngine;
  internal: InternalApi;
}

const kInitializeSeed = 0x5eed;

// Owns one wasmoon Lua state configured identically to the host plugin's
// script engine: internals first (captures debug.sethook), then the shared
// prelude, then log wiring + sandbox. Hook calls are synchronous so the
// playback loop can evaluate frames without awaiting.
//
// The state is created once and reused across every hook call, matching the
// native ScriptEngine::Impl lifetime. Scripts rely on that: a plain Lua global
// written in OnPreLayout must still be readable in OnLayout on the same frame
// Do not recreate the state or reset globals between hook calls -- doing so
// would make the simulator diverge from the plugin and silently break scripts
// that use this handoff.
export class ScriptEngine {
  private constructor(
    private readonly options: ScriptEngineOptions,
    private lua: LuaEngine,
    private internal: InternalApi,
  ) {}

  static async create(options: ScriptEngineOptions): Promise<ScriptEngine> {
    const runtime = await createRuntime(options);
    return new ScriptEngine(options, runtime.lua, runtime.internal);
  }

  // Replaces the loaded user script atomically. Compilation and top-level
  // execution happen in a candidate state; the active script is retained if
  // either step fails.
  async loadScript(
    source: string,
    chunkName = "@user-script.lua",
  ): Promise<{ ok: boolean; message?: string }> {
    const candidate = await createRuntime(this.options);
    let result: { ok: boolean; message?: string } = { ok: true };
    const loadResult = candidate.internal.loadChunk(source, chunkName);
    if (loadResult.ok) {
      this.lua.global.close();
      this.lua = candidate.lua;
      this.internal = candidate.internal;
    } else {
      candidate.lua.global.close();
      result = {
        ok: false,
        message: loadResult.message,
      };
    }
    return result;
  }

  hasHook(hookName: string): boolean {
    return this.internal.hasHook(hookName);
  }

  callHook(hookName: string, phase: "pre_layout" | "layout" | "path" | "init", data: unknown, seed?: number): HookResult {
    // wasmoon passes JS objects into Lua by reference, so a hook that errors
    // midway would leave partial writes in the caller's object. Hooks run
    // against a clone; the caller's input is never mutated and the error
    // policy (fall back to unmodified values) holds.
    const dataCopy = structuredClone(data);
    const raw = this.internal.callHook(hookName, dataCopy, phase, seed);
    return {
      ok: raw.ok,
      message: raw.message,
      globalWrites: raw.global_writes ? Object.values(raw.global_writes) : [],
      data: raw.ok ? raw.data : undefined,
    };
  }

  // Rebuilds mt.storage from scratch, runs OnInitialize, then freezes the
  // result. Returns the frozen storage contents for display.
  runInitialize(initData: unknown): HookResult & { storage?: unknown } {
    this.internal.beginInitialize(kInitializeSeed);
    const result = this.callHook("OnInitialize", "init", initData, kInitializeSeed);
    this.internal.finishInitialize();
    return { ...result, storage: this.internal.storageSnapshot() };
  }

  // Direct state access for tests and diagnostics; production callers go
  // through loadScript / callHook.
  async run(source: string): Promise<void> {
    await this.lua.doString(source);
  }

  getGlobal(name: string): unknown {
    return this.lua.global.get(name);
  }

  dispose(): void {
    this.lua.global.close();
  }
}

async function createRuntime(options: ScriptEngineOptions): Promise<LuaRuntime> {
  const factory = new LuaFactory(options.wasmUri);
  const lua = await factory.createEngine();
  await lua.doString(kInternalsChunk);
  const internal = lua.global.get("__mtInternal") as InternalApi;
  loadRequiredChunk(internal, options.preludeSource, "@mt/prelude.lua");
  loadRequiredChunk(
    internal,
    makeLuaDiagnosticsChunk(options.preludeSource),
    "@mt/diagnostics.lua",
  );
  lua.global.set("__mtJsLog", options.log);
  loadRequiredChunk(internal, kSandboxChunk, "@mt/sandbox.lua");
  return { lua, internal };
}

function loadRequiredChunk(internal: InternalApi, source: string, chunkName: string): void {
  const result = internal.loadChunk(source, chunkName);
  if (!result.ok) {
    throw new Error(result.message ?? `failed to load ${chunkName}`);
  }
}
