import type { LuaCompletionTarget, LuaHookPhase } from "./scriptingApi";

export interface LuaCompletionContext {
  target: LuaCompletionTarget | "root";
  phase: LuaHookPhase;
}

export function resolveLuaCompletionContext(sourceBeforeCursor: string): LuaCompletionContext {
  const phase = resolveHookPhase(sourceBeforeCursor);
  // The trailing separator is "." for field access and ":" for a method call
  // (path:at_distance), so both terminate a receiver.
  const receiverMatch = /([A-Za-z_]\w*(?:\s*\[[^\]\r\n]+\])?(?:\.[A-Za-z_]\w*(?:\s*\[[^\]\r\n]+\])?)*)[.:]\s*$/.exec(
    sourceBeforeCursor,
  );
  const receiver = receiverMatch?.[1].replace(/\s+/g, "") ?? "";
  return { target: resolveReceiver(receiver, sourceBeforeCursor), phase };
}

function resolveHookPhase(source: string): LuaHookPhase {
  const initializeIndex = source.lastIndexOf("function OnInitialize");
  const baseIndex = source.lastIndexOf("function OnPreLayout");
  const layoutIndex = source.lastIndexOf("function OnLayout");
  const pathIndex = source.lastIndexOf("function OnPath");
  const latestIndex = Math.max(initializeIndex, baseIndex, layoutIndex, pathIndex);
  let phase: LuaHookPhase = "layout";
  if (latestIndex >= 0 && latestIndex === initializeIndex) {
    phase = "initialize";
  } else if (latestIndex >= 0 && latestIndex === baseIndex) {
    phase = "pre_layout";
  } else if (latestIndex >= 0 && latestIndex === pathIndex) {
    phase = "path";
  }
  return phase;
}

function resolveReceiver(
  receiver: string,
  sourceBeforeCursor: string,
): LuaCompletionTarget | "root" {
  let target: LuaCompletionTarget | "root" = "root";
  if (receiver === "ctx") {
    target = "ctx";
  } else if (receiver === "ctx.canvas") {
    target = "canvas";
  } else if (receiver === "ctx.timeline") {
    target = "timeline";
  } else if (receiver === "ctx.font") {
    target = "font";
  } else if (receiver === "ctx.meta") {
    target = "meta";
  } else if (receiver === "ctx.meta.capabilities") {
    target = "capabilities";
  } else if (receiver === "ctx.meta.limits") {
    target = "limits";
  } else if (receiver === "ctx.global") {
    target = "global";
  } else if (receiver === "ctx.global.fill") {
    target = "global_fill";
  } else if (receiver === "ctx.global.gradient") {
    target = "gradient";
  } else if (receiver === "ctx.global.stroke") {
    target = "global_stroke";
  } else if (receiver === "ctx.global.shadow") {
    target = "global_shadow";
  } else if (receiver === "ctx.camera") {
    target = "camera";
  } else if (receiver === "ctx.paths") {
    target = "path_collection";
  } else if (/^ctx\.chars\[[^\]]+\]$/.test(receiver)) {
    target = "character";
  } else if (/^ctx\.chars\[[^\]]+\]\.geometry$/.test(receiver)) {
    target = "character_geometry";
  } else if (/^ctx\.chars\[[^\]]+\]\.fill$/.test(receiver)) {
    target = "individual_fill";
  } else if (/^ctx\.chars\[[^\]]+\]\.stroke$/.test(receiver)) {
    target = "individual_stroke";
  } else if (/^ctx\.chars\[[^\]]+\]\.shadow$/.test(receiver)) {
    target = "individual_shadow";
  } else if (/^ctx\.parts\[[^\]]+\]$/.test(receiver)) {
    target = "part";
  } else if (/^ctx\.parts\[[^\]]+\]\.geometry$/.test(receiver)) {
    target = "part_geometry";
  } else if (/^ctx\.parts\[[^\]]+\]\.fill$/.test(receiver)) {
    target = "individual_fill";
  } else if (/^ctx\.parts\[[^\]]+\]\.stroke$/.test(receiver)) {
    target = "individual_stroke";
  } else if (/^ctx\.parts\[[^\]]+\]\.shadow$/.test(receiver)) {
    target = "individual_shadow";
  } else if (receiver === "ctx.bounding_box") {
    target = "bounding_box";
  } else if (receiver === "ctx.output") {
    target = "output";
  } else if (receiver === "mt") {
    target = "mt";
  } else if (receiver === "mt.ease") {
    target = "ease";
  } else if (receiver === "mt.color") {
    target = "color_utilities";
  } else if (receiver === "mt.path") {
    target = "path_utilities";
  } else if (receiver === "mt.layout") {
    target = "layout_utilities";
  } else if (receiver === "mt.timeline") {
    target = "timeline_utilities";
  } else if (receiver === "mt.text") {
    target = "text_utilities";
  } else if (/^[A-Za-z_]\w*\.path$/.test(receiver)) {
    const aliasTarget = resolveAlias(receiver.slice(0, -".path".length), sourceBeforeCursor);
    if (aliasTarget === "path_part") {
      target = "drawing_path";
    }
  } else if (isColorReceiver(receiver, sourceBeforeCursor)) {
    target = "color";
  } else if (/^[A-Za-z_]\w*\.geometry$/.test(receiver)) {
    const aliasTarget = resolveAlias(receiver.slice(0, -".geometry".length), sourceBeforeCursor);
    if (aliasTarget === "character") {
      target = "character_geometry";
    } else if (aliasTarget === "part") {
      target = "part_geometry";
    }
  } else if (/^[A-Za-z_]\w*\.(?:fill|stroke|shadow)$/.test(receiver)) {
    const separatorIndex = receiver.lastIndexOf(".");
    const groupName = receiver.slice(separatorIndex + 1);
    const aliasTarget = resolveAlias(receiver.slice(0, separatorIndex), sourceBeforeCursor);
    if (aliasTarget === "character" || aliasTarget === "part") {
      target = groupName === "fill"
        ? "individual_fill"
        : groupName === "stroke"
          ? "individual_stroke"
          : "individual_shadow";
    }
  } else if (/^[A-Za-z_]\w*$/.test(receiver)) {
    target = resolveAlias(receiver, sourceBeforeCursor);
  }
  return target;
}

function isColorReceiver(receiver: string, source: string): boolean {
  const colorSuffix = /(?:\.color|\.end_color|\.fill_color)$/;
  let result = colorSuffix.test(receiver);
  if (!result && /^[A-Za-z_]\w*$/.test(receiver)) {
    const escaped = escapeRegExp(receiver);
    result = new RegExp(
      `local\\s+${escaped}\\s*=\\s*(?:ctx\\.global|ctx\\.chars\\s*\\[[^\\]]+\\]|ctx\\.parts\\s*\\[[^\\]]+\\])\\.(?:fill|stroke|shadow|gradient)\\.(?:color|end_color)\\b`,
    ).test(source);
  }
  return result;
}

// How an alias can come to hold an API object. The last binding to win is the
// one nearest the cursor, so a name rebound part-way through a script resolves
// to whatever it holds at that point.
//
// Two binding forms are recognised: a direct `local x = <expression>`, and a
// generic-for loop variable such as `for _, part in ipairs(<collection>)`,
// which is how scripts normally walk ctx.chars, ctx.parts and the part lists
// returned by ctx.paths.
const kAliasBindings: ReadonlyArray<{
  target: LuaCompletionTarget;
  // Matched against the right-hand side of a `local` binding.
  assigned?: string;
  // Matched against the collection an ipairs() loop iterates over. The loop
  // variable holds one element, so the target is the element's type.
  iterated?: string;
}> = [
  { target: "character", assigned: "ctx\\.chars\\s*\\[[^\\]]+\\]", iterated: "ctx\\.chars" },
  { target: "part", assigned: "ctx\\.parts\\s*\\[[^\\]]+\\]", iterated: "ctx\\.parts" },
  {
    target: "path_part",
    assigned: "ctx\\.paths:part\\s*\\(",
    // :character() and :select() both return arrays of parts.
    iterated: "ctx\\.paths:(?:character|select)\\s*\\(",
  },
  { target: "arc_length_path", assigned: "mt\\.path\\.arc_length\\s*\\(" },
];

function resolveAlias(alias: string, source: string): LuaCompletionTarget | "root" {
  const escaped = escapeRegExp(alias);
  let target: LuaCompletionTarget | "root" = "root";
  let latestIndex = -1;
  for (const binding of kAliasBindings) {
    const patterns: string[] = [];
    if (binding.assigned !== undefined) {
      patterns.push(`local\\s+${escaped}\\s*=\\s*${binding.assigned}`);
    }
    if (binding.iterated !== undefined) {
      // The loop variable is the last name before "in"; an optional leading
      // index variable ("for i, char in ...") is skipped.
      patterns.push(
        `for\\s+(?:[A-Za-z_]\\w*\\s*,\\s*)?${escaped}\\s+in\\s+ipairs\\s*\\(\\s*${binding.iterated}`,
      );
    }
    for (const pattern of patterns) {
      const index = lastMatchIndex(new RegExp(pattern, "g"), source);
      if (index > latestIndex) {
        latestIndex = index;
        target = binding.target;
      }
    }
  }
  return target;
}

function lastMatchIndex(pattern: RegExp, source: string): number {
  let result = -1;
  for (const match of source.matchAll(pattern)) {
    result = match.index;
  }
  return result;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

export function isMugTypographyScript(source: string): boolean {
  const maxLinesToCheck = 5;
  const lines = source.split(/\r?\n/).slice(0, maxLinesToCheck);
  const magicCommentPattern = /--\s*@(?:mug|mt|mugtypography)\b/i;
  let isMugTypography = false;
  for (const line of lines) {
    if (magicCommentPattern.test(line)) {
      isMugTypography = true;
      break;
    }
  }
  return isMugTypography;
}

// The script's own "-- @title" directive, which names exported files (see
// WebHostAdapter.saveVideo / saveThumbnail) and identifies a gallery entry
// once it is submitted. Kept apart from parseMugMetadata because that
// describes the scene to set up, while this is only a label for the script.
export function parseScriptTitle(source: string): string {
  // Horizontal whitespace only: plain \s would let a valueless "-- @title"
  // swallow the following line as its value.
  const match = /^--[^\S\r\n]*@title[^\S\r\n]+(.+)$/m.exec(source);
  return match === null ? "" : match[1].trim();
}

// Reduces a title to something safe to hand a filesystem: the exported name
// is a download's suggested file name, so path separators and characters
// Windows rejects must not survive it. An empty result means the caller
// should fall back to its own default rather than emit a nameless file.
export function toFileNameSlug(title: string): string {
  return title
    .replace(/[\\/:*?"<>|]+/g, " ")
    .replace(/\s+/g, "_")
    .replace(/^[._]+|[._]+$/g, "")
    .slice(0, 60);
}

import type { Rgba } from "./sceneSchema";

export interface MugMetadata {
  projection3D?: boolean;
  durationSeconds?: number;
  backgroundColor?: Rgba;
  checkerboardBackground?: boolean;
  positionX?: number;
  positionY?: number;
  fontLang?: string;
  text?: string;
}

// Kana and CJK ideographs, i.e. what makes a recommended text need a font with
// CJK coverage. Han alone is shared with Chinese, but the simulator only tells
// "needs a CJK font" from "Latin is enough", so it does not try to separate
// those; anything in these ranges resolves to "ja".
const kCjkTextPattern =
  /[　-〿぀-ヿㇰ-ㇿ㐀-䶿一-鿿豈-﫿＀-￯]/;

// Infers the font language from a recommended text, so `@recommend text` alone
// is enough for Japanese samples and `lang` only has to be spelled out when it
// disagrees with the text (or when no text is recommended at all).
export function inferFontLanguage(text: string): string | undefined {
  let result: string | undefined;
  if (kCjkTextPattern.test(text)) {
    result = "ja";
  }
  return result;
}

export function parseHexColor(hex: string): Rgba | undefined {
  const cleanHex = hex.trim().replace(/^#/, "");
  if (cleanHex.length === 6) {
    const r = parseInt(cleanHex.substring(0, 2), 16) / 255;
    const g = parseInt(cleanHex.substring(2, 4), 16) / 255;
    const b = parseInt(cleanHex.substring(4, 6), 16) / 255;
    if (Number.isFinite(r) && Number.isFinite(g) && Number.isFinite(b)) {
      return { r, g, b, a: 1 };
    }
  } else if (cleanHex.length === 8) {
    const r = parseInt(cleanHex.substring(0, 2), 16) / 255;
    const g = parseInt(cleanHex.substring(2, 4), 16) / 255;
    const b = parseInt(cleanHex.substring(4, 6), 16) / 255;
    const a = parseInt(cleanHex.substring(6, 8), 16) / 255;
    if (Number.isFinite(r) && Number.isFinite(g) && Number.isFinite(b) && Number.isFinite(a)) {
      return { r, g, b, a };
    }
  }
  return undefined;
}

// Resolves the escapes allowed inside a quoted `@recommend text "..."` value:
// `\n` for a line break, plus `\"`, `\'` and `\\` so quotes and backslashes can
// be written literally. Any other escape keeps its backslash, since inventing
// meanings for unknown escapes would silently mangle text.
function unescapeMetadataText(value: string): string {
  return value.replace(/\\(.)/g, (match, character: string) => {
    let result = match;
    if (character === "n") {
      result = "\n";
    } else if (character === '"' || character === "'" || character === "\\") {
      result = character;
    }
    return result;
  });
}

// Directive lines (`-- @MugTypography`, `-- @duration`, `-- @required`, ...)
// live in the header, as consecutive single-line `--` comments at the top of
// the file. The header ends at the first `--[[` block comment (the
// `@description` body) or the first non-comment line, whichever comes first,
// so scripts with a long description still have every directive recognized
// regardless of length.
function collectHeaderDirectiveLines(source: string): string[] {
  const lines = source.split(/\r?\n/);
  const directiveLines: string[] = [];
  for (const line of lines) {
    if (/^--\[\[/.test(line)) {
      break;
    }
    if (/^--/.test(line)) {
      directiveLines.push(line);
    } else {
      break;
    }
  }
  return directiveLines;
}

export function parseMugMetadata(source: string): MugMetadata {
  const lines = collectHeaderDirectiveLines(source);
  const requiredPattern = /--\s*@required\s*(?:3d|3dprojection)\b/i;
  const durationPattern = /--\s*@duration\s*(\d+(?:\.\d+)?)\b/i;
  const recommendPattern = /--\s*@recommend(?:\.|\s+)(.*)$/i;

  let projection3D: boolean | undefined;
  let durationSeconds: number | undefined;
  let backgroundColor: Rgba | undefined;
  let checkerboardBackground: boolean | undefined;
  let positionX: number | undefined;
  let positionY: number | undefined;
  let fontLang: string | undefined;
  let text: string | undefined;

  // A recommended text is quoted, since unlike the other keys its value may
  // contain spaces: `-- @recommend text "うふふふ"`. Either quote style works
  // (the backreference keeps the closing quote matched to the opening one), so
  // the other style can appear literally inside. Within the quotes, a `\n`
  // escape becomes a real newline so multi-line samples stay writable in a
  // single-line comment. The quotes also delimit the value, so this key can
  // share a line with the others.
  const textPattern = /\b(?:text|sample_text)\s+(["'])((?:[^\\]|\\.)*?)\1/i;

  for (const line of lines) {
    if (requiredPattern.test(line)) {
      projection3D = true;
    }
    const durationMatch = durationPattern.exec(line);
    if (durationMatch !== null) {
      const parsed = parseFloat(durationMatch[1]);
      if (Number.isFinite(parsed) && parsed > 0) {
        durationSeconds = parsed;
      }
    }
    const recommendMatch = recommendPattern.exec(line);
    if (recommendMatch !== null) {
      const body = recommendMatch[1].trim();
      const textMatch = textPattern.exec(body);
      if (textMatch !== null) {
        text = unescapeMetadataText(textMatch[2]);
      }
      if (/\b(?:checkerboard|checker)\b/i.test(body)) {
        checkerboardBackground = true;
      }
      if (/\bsolid\b/i.test(body)) {
        checkerboardBackground = false;
      }
      const hexMatch = /(#[0-9a-fA-F]{6,8})\b/.exec(body);
      if (hexMatch !== null) {
        const parsedColor = parseHexColor(hexMatch[1]);
        if (parsedColor !== undefined) {
          backgroundColor = parsedColor;
        }
      }
      const posMatch = /\b(?:pos|position|global_pos)\s+(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)\b/i.exec(body);
      if (posMatch !== null) {
        const x = parseFloat(posMatch[1]);
        const y = parseFloat(posMatch[2]);
        if (Number.isFinite(x) && Number.isFinite(y)) {
          positionX = x;
          positionY = y;
        }
      }
      const langMatch = /\b(?:lang|font_lang|fontLang)\s+([a-zA-Z0-9_-]+)\b/i.exec(body);
      if (langMatch !== null) {
        fontLang = langMatch[1];
      }
    }
  }

  // An explicit `lang` always wins; otherwise the recommended text implies it.
  if (fontLang === undefined && text !== undefined) {
    fontLang = inferFontLanguage(text);
  }

  return {
    projection3D,
    durationSeconds,
    backgroundColor,
    checkerboardBackground,
    positionX,
    positionY,
    fontLang,
    text,
  };
}
