import type { Rgba } from "../shared/sceneSchema";

export function formatOutputValue(value: unknown): string {
  let result: string;
  if (typeof value === "number") {
    result = Number.isFinite(value) ? String(Number(value.toFixed(6))) : String(value);
  } else if (typeof value === "string") {
    result = value;
  } else if (typeof value === "boolean") {
    result = value ? "true" : "false";
  } else if (Array.isArray(value)) {
    result = `[${value.map(formatOutputValue).join(", ")}]`;
  } else if (isRgba(value)) {
    result = `rgba(${formatOutputValue(value.r)}, ${formatOutputValue(value.g)}, ${formatOutputValue(value.b)}, ${formatOutputValue(value.a)})`;
  } else if (value === undefined) {
    result = "undefined";
  } else if (value === null) {
    result = "null";
  } else {
    result = JSON.stringify(value);
  }
  return result;
}

export function outputValuesEqual(first: unknown, second: unknown): boolean {
  let result = Object.is(first, second);
  if (!result && Array.isArray(first) && Array.isArray(second) && first.length === second.length) {
    result = first.every((value, index) => outputValuesEqual(value, second[index]));
  } else if (!result && isRecord(first) && isRecord(second)) {
    const firstKeys = Object.keys(first);
    const secondKeys = Object.keys(second);
    result =
      firstKeys.length === secondKeys.length &&
      firstKeys.every(
        (key) => Object.hasOwn(second, key) && outputValuesEqual(first[key], second[key]),
      );
  }
  return result;
}

export function isRgba(value: unknown): value is Rgba {
  return (
    isRecord(value) &&
    typeof value.r === "number" &&
    typeof value.g === "number" &&
    typeof value.b === "number" &&
    typeof value.a === "number"
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
