export type SimulatorPage = "global" | "camera" | "characters" | "parts" | "output";
export type InspectorPage = "simulator" | SimulatorPage;

export interface PageDefinition<Page extends string> {
  id: Page;
  label: string;
  title: string;
}

// Mirrors the host's simulator-relevant Page parameter options. Compact labels
// keep the tabs usable in the narrow inspector while titles retain host names.
export const simulatorPages: readonly PageDefinition<SimulatorPage>[] = [
  { id: "global", label: "Global", title: "Global Settings" },
  { id: "camera", label: "Camera", title: "Camera Settings" },
  { id: "characters", label: "Character", title: "Character Settings" },
  { id: "parts", label: "Part", title: "Part Settings" },
  { id: "output", label: "Output", title: "Output Settings" },
];

export const inspectorPages: readonly PageDefinition<InspectorPage>[] = [
  { id: "simulator", label: "Simulator", title: "Simulator Settings" },
  ...simulatorPages,
];
