// Declared as an array rather than a bare union so tests can walk every target
// and check that each one resolves to a real API reference anchor. A union
// alone cannot be enumerated at runtime, which is how several targets silently
// fell through to the generic "context" section.
export const kLuaCompletionTargets = [
  "ctx",
  "canvas",
  "timeline",
  "font",
  "meta",
  "capabilities",
  "limits",
  "global",
  "global_fill",
  "gradient",
  "global_stroke",
  "global_shadow",
  "camera",
  "character",
  "character_geometry",
  "part",
  "part_geometry",
  "path_collection",
  "path_part",
  "drawing_path",
  "individual_fill",
  "individual_stroke",
  "individual_shadow",
  "bounding_box",
  "output",
  "color",
  "mt",
  "ease",
  "color_utilities",
  "layout_utilities",
  "path_utilities",
  "arc_length_path",
  "timeline_utilities",
  "text_utilities",
] as const;

export type LuaCompletionTarget = (typeof kLuaCompletionTargets)[number];

export type LuaHookPhase = "initialize" | "pre_layout" | "layout" | "path";

// API compatibility advances independently from the product version.
export const kScriptApiLevel = 5;
export { kPluginVersion } from "./pluginVersion.generated";

export interface LuaApiMember {
  name: string;
  type: string;
  description: string;
  descriptionJa: string;
  readIn: readonly LuaHookPhase[];
  writeIn: readonly LuaHookPhase[];
  // Lua API level this member has been available since (schema "since").
  since: number;
  values?: readonly string[];
  parameters?: readonly string[];
  returns?: string;
  deprecated?: boolean;
  reference?: {
    file: string;
    anchor: string;
  };
  // Lower/upper bounds the host clamps a written number to before use, if any
  // (schema "min"/"max"). Fields with no configured bound omit these.
  min?: number;
  max?: number;
}

