import type { Rgba } from "../shared/sceneSchema";
import type { EvaluatedFrame } from "../core/frameEvaluator";
import { rgbaToCompactLabel, rgbaToCss } from "../core/color";
import { formatOutputValue, isRgba, outputValuesEqual } from "../core/outputValueFormat";
import { simulatorPages, type SimulatorPage } from "../shared/simulatorPages";
import {
  cameraMembers,
  boundingBoxMembers,
  characterMembers,
  globalMembers,
  globalFillMembers,
  gradientMembers,
  globalStrokeMembers,
  globalShadowMembers,
  individualFillMembers,
  individualStrokeMembers,
  individualShadowMembers,
  outputMembers,
  partMembers,
  type LuaApiMember,
} from "../shared/scriptingApi";

type OutputCategory = "global" | "camera" | "characters" | "parts" | "boundingBox" | "output";
type ParameterRecord = Record<string, unknown>;

interface ValueCellBinding {
  cell: HTMLTableCellElement;
  category: OutputCategory;
  field: string;
  index?: number;
}

const kCharacterMarginField = "margin_after";

// Nested group fields (ctx.global.stroke etc.) render as one row per member
// using a dotted path such as "stroke.width".
const kGroupMembersByType: Readonly<Record<string, readonly LuaApiMember[]>> = {
  MtGlobalFill: globalFillMembers,
  MtGradient: gradientMembers,
  MtGlobalStroke: globalStrokeMembers,
  MtGlobalShadow: globalShadowMembers,
  MtIndividualFill: individualFillMembers,
  MtIndividualStroke: individualStrokeMembers,
  MtIndividualShadow: individualShadowMembers,
};

function expandFieldNames(members: readonly LuaApiMember[]): string[] {
  return members.flatMap((member) => {
    const groupMembers = kGroupMembersByType[member.type];
    return groupMembers === undefined
      ? [member.name]
      : groupMembers.map(({ name }) => `${member.name}.${name}`);
  });
}

function readFieldPath(record: ParameterRecord, field: string): unknown {
  let value: unknown = record;
  for (const segment of field.split(".")) {
    if (value === null || typeof value !== "object") {
      return undefined;
    }
    value = (value as ParameterRecord)[segment];
  }
  return value;
}

// Per-character margins render as the "margin_after" row on the Character tab instead, one row per
// character, so the aggregate array field is excluded from the flat Global property table.
const kGlobalFields = expandFieldNames(globalMembers).filter((name) => name !== "margins");
const kCameraFields = cameraMembers.map(({ name }) => name);
const kBoundingBoxFields = boundingBoxMembers.map(({ name }) => name);
const kOutputFields = outputMembers.map(({ name }) => name);
const kCharacterFields = [kCharacterMarginField, ...expandFieldNames(characterMembers)];
const kPartFields = expandFieldNames(partMembers);

const kIndexColumnWidth = 48;
const kPropertyNameColumnWidth = 180;
const kPropertyValueColumnWidth = 360;
const kIndexedValueColumnWidth = 148;

export class OutputValuesView {
  private readonly pageTabs = new Map<SimulatorPage, HTMLButtonElement>();
  private readonly tableHost: HTMLElement;
  private selectedPage: SimulatorPage = "global";
  private lastFrame: EvaluatedFrame | undefined;
  private renderedSignature = "";
  private valueCellBindings: ValueCellBinding[] = [];

  constructor(container: HTMLElement) {
    const panel = document.createElement("section");
    panel.className = "output-values";
    const initialCollapsed = localStorage.getItem("mt-output-values-collapsed") === "true";
    if (initialCollapsed) {
      panel.classList.add("collapsed");
    }

    const header = document.createElement("header");
    header.className = "output-values-header";
    const title = document.createElement("strong");
    title.textContent = "Script Output Values";
    const tabs = document.createElement("div");
    tabs.className = "panel-tabs output-values-tabs";
    tabs.role = "tablist";
    for (const page of simulatorPages) {
      const button = document.createElement("button");
      button.type = "button";
      button.role = "tab";
      button.textContent = page.label;
      button.title = page.title;
      button.className = "panel-tab";
      button.addEventListener("click", () => this.selectPage(page.id));
      tabs.appendChild(button);
      this.pageTabs.set(page.id, button);
    }
    this.updatePageTabs();

    const collapseButton = document.createElement("button");
    collapseButton.type = "button";
    collapseButton.className = "output-values-collapse-button";
    collapseButton.title = initialCollapsed ? "Expand Script Output Values" : "Collapse Script Output Values";
    collapseButton.textContent = initialCollapsed ? "▲" : "▼";
    collapseButton.addEventListener("click", () => {
      const isCollapsed = panel.classList.toggle("collapsed");
      localStorage.setItem("mt-output-values-collapsed", String(isCollapsed));
      collapseButton.textContent = isCollapsed ? "▲" : "▼";
      collapseButton.title = isCollapsed ? "Expand Script Output Values" : "Collapse Script Output Values";
    });

    header.append(collapseButton, title, tabs);
    this.tableHost = document.createElement("div");
    this.tableHost.className = "output-values-table-host";
    panel.append(header, this.tableHost);
    container.appendChild(panel);
  }

  render(frame: EvaluatedFrame): void {
    this.lastFrame = frame;
    this.renderCurrentPage();
  }

  private selectPage(page: SimulatorPage): void {
    if (this.selectedPage !== page) {
      this.selectedPage = page;
      this.updatePageTabs();
      this.renderCurrentPage();
    }
  }

  private updatePageTabs(): void {
    for (const [page, button] of this.pageTabs) {
      const selected = page === this.selectedPage;
      button.classList.toggle("panel-tab-active", selected);
      button.setAttribute("aria-selected", String(selected));
    }
  }

  private renderCurrentPage(): void {
    const frame = this.lastFrame;
    if (frame === undefined) {
      return;
    }
    const rowCount = this.getRowCount(frame, this.selectedPage);
    const signature = `${this.selectedPage}:${rowCount}`;
    if (signature !== this.renderedSignature) {
      this.valueCellBindings = [];
      this.tableHost.replaceChildren(this.makePageContent(this.selectedPage, rowCount));
      this.renderedSignature = signature;
    }
    this.updateValueCells(frame);
  }

  private getRowCount(frame: EvaluatedFrame, page: SimulatorPage): number {
    let rowCount = 1;
    if (page === "characters") {
      rowCount = frame.scriptOutputValues.characters.length;
    } else if (page === "parts") {
      rowCount = frame.scriptOutputValues.parts.length;
    }
    return rowCount;
  }

  private makePageContent(page: SimulatorPage, rowCount: number): HTMLElement {
    const content = document.createElement("div");
    content.className = "output-values-page";
    if (page === "global") {
      content.append(
        this.makeTableGroup("Global", this.makeCategoryTable("global", 1)),
        this.makeTableGroup("Bounding Box", this.makeCategoryTable("boundingBox", 1)),
      );
    } else {
      content.appendChild(this.makeCategoryTable(page, rowCount));
    }
    return content;
  }

  private makeTableGroup(title: string, table: HTMLTableElement): HTMLElement {
    const group = document.createElement("section");
    group.className = "output-values-group";
    const heading = document.createElement("h3");
    heading.textContent = title;
    group.append(heading, table);
    return group;
  }

  private makeCategoryTable(category: OutputCategory, rowCount: number): HTMLTableElement {
    let table: HTMLTableElement;
    switch (category) {
      case "global":
        table = this.makePropertyTable(category, kGlobalFields);
        break;
      case "camera":
        table = this.makePropertyTable(category, kCameraFields);
        break;
      case "boundingBox":
        table = this.makePropertyTable(category, kBoundingBoxFields);
        break;
      case "output":
        table = this.makePropertyTable(category, kOutputFields);
        break;
      case "characters":
        table = this.makeIndexedTable(category, rowCount, kCharacterFields);
        break;
      case "parts":
        table = this.makeIndexedTable(category, rowCount, kPartFields);
        break;
    }
    return table;
  }

  private makePropertyTable(
    category: OutputCategory,
    fields: readonly PropertyKey[],
  ): HTMLTableElement {
    const table = this.makeTable(
      ["Parameter", "Output"],
      [kPropertyNameColumnWidth, kPropertyValueColumnWidth],
    );
    const body = document.createElement("tbody");
    for (const field of fields) {
      const row = document.createElement("tr");
      const name = document.createElement("th");
      name.scope = "row";
      name.textContent = String(field);
      row.append(name, this.makeValueCell(category, String(field)));
      body.appendChild(row);
    }
    table.appendChild(body);
    return table;
  }

  private makeIndexedTable(
    category: OutputCategory,
    rowCount: number,
    fields: readonly PropertyKey[],
  ): HTMLTableElement {
    const table = this.makeTable(
      ["#", ...fields.map(String)],
      [kIndexColumnWidth, ...fields.map(() => kIndexedValueColumnWidth)],
    );
    const body = document.createElement("tbody");
    for (let index = 0; index < rowCount; index += 1) {
      const row = document.createElement("tr");
      const indexCell = document.createElement("th");
      indexCell.scope = "row";
      indexCell.textContent = String(index + 1);
      row.appendChild(indexCell);
      for (const field of fields) {
        row.appendChild(this.makeValueCell(category, String(field), index));
      }
      body.appendChild(row);
    }
    table.appendChild(body);
    return table;
  }

  private makeTable(headers: string[], columnWidths: number[]): HTMLTableElement {
    const table = document.createElement("table");
    table.className = "output-values-table";
    const columnGroup = document.createElement("colgroup");
    for (const width of columnWidths) {
      const column = document.createElement("col");
      column.style.width = `${width}px`;
      columnGroup.appendChild(column);
    }
    table.style.width = `max(100%, ${columnWidths.reduce((sum, width) => sum + width, 0)}px)`;
    table.appendChild(columnGroup);
    const header = document.createElement("thead");
    const row = document.createElement("tr");
    for (const text of headers) {
      const cell = document.createElement("th");
      cell.textContent = text;
      row.appendChild(cell);
    }
    header.appendChild(row);
    table.appendChild(header);
    return table;
  }

  private makeValueCell(
    category: OutputCategory,
    field: string,
    index?: number,
  ): HTMLTableCellElement {
    const cell = document.createElement("td");
    cell.dataset.outputField = field;
    if (index !== undefined) {
      cell.dataset.outputIndex = String(index);
    }
    this.valueCellBindings.push({ cell, category, field, index });
    return cell;
  }

  private updateValueCells(frame: EvaluatedFrame): void {
    for (const binding of this.valueCellBindings) {
      if (binding.category === "characters" && binding.field === kCharacterMarginField) {
        const index = binding.index ?? 0;
        this.updateValueCell(
          binding.cell,
          frame.scriptInputValues.global.margins[index],
          frame.scriptOutputValues.global.margins[index],
        );
        continue;
      }
      const [before, after] = this.getParameterRecords(frame, binding);
      this.updateValueCell(binding.cell, readFieldPath(before, binding.field), readFieldPath(after, binding.field));
    }
  }

  private getParameterRecords(
    frame: EvaluatedFrame,
    binding: ValueCellBinding,
  ): [ParameterRecord, ParameterRecord] {
    let before: ParameterRecord;
    let after: ParameterRecord;
    switch (binding.category) {
      case "global":
        before = frame.scriptInputValues.global as unknown as ParameterRecord;
        after = frame.scriptOutputValues.global as unknown as ParameterRecord;
        break;
      case "camera":
        before = frame.scriptInputValues.camera as unknown as ParameterRecord;
        after = frame.scriptOutputValues.camera as unknown as ParameterRecord;
        break;
      case "boundingBox":
        before = frame.scriptInputValues.boundingBox as unknown as ParameterRecord;
        after = frame.scriptOutputValues.boundingBox as unknown as ParameterRecord;
        break;
      case "output":
        before = frame.scriptInputValues.output as unknown as ParameterRecord;
        after = frame.scriptOutputValues.output as unknown as ParameterRecord;
        break;
      case "characters":
        before = (frame.scriptInputValues.characters as unknown as ParameterRecord[])[binding.index ?? 0] ?? {};
        after = (frame.scriptOutputValues.characters as unknown as ParameterRecord[])[binding.index ?? 0] ?? {};
        break;
      case "parts":
        before = (frame.scriptInputValues.parts as unknown as ParameterRecord[])[binding.index ?? 0] ?? {};
        after = (frame.scriptOutputValues.parts as unknown as ParameterRecord[])[binding.index ?? 0] ?? {};
        break;
    }
    return [before, after];
  }

  private updateValueCell(cell: HTMLTableCellElement, before: unknown, after: unknown): void {
    if (isRgba(before) && isRgba(after)) {
      this.updateColorValueCell(cell, before, after);
      return;
    }
    const outputText = formatOutputValue(after);
    let text = outputText;
    let title = outputText;
    let className = "";
    if (outputValuesEqual(before, after)) {
      text = outputText;
    } else {
      const inputText = formatOutputValue(before);
      className = "output-value-changed";
      text = `${inputText} → ${outputText}`;
      title = `Input: ${inputText}\nOutput: ${outputText}`;
    }
    if (cell.textContent !== text) {
      cell.textContent = text;
    }
    if (cell.className !== className) {
      cell.className = className;
    }
    if (cell.title !== title) {
      cell.title = title;
    }
  }

  private updateColorValueCell(
    cell: HTMLTableCellElement,
    before: Rgba,
    after: Rgba,
  ): void {
    let content = cell.firstElementChild;
    if (!(content instanceof HTMLElement) || !content.classList.contains("output-color-content")) {
      content = document.createElement("span");
      content.className = "output-color-content";
      const inputSwatch = document.createElement("span");
      inputSwatch.className = "output-color-swatch output-color-input";
      const arrow = document.createElement("span");
      arrow.className = "output-color-arrow";
      arrow.textContent = "→";
      const outputSwatch = document.createElement("span");
      outputSwatch.className = "output-color-swatch output-color-output";
      const label = document.createElement("span");
      label.className = "output-color-label";
      content.append(inputSwatch, arrow, outputSwatch, label);
      cell.replaceChildren(content);
    }

    const changed = !outputValuesEqual(before, after);
    const inputSwatch = content.querySelector<HTMLElement>(".output-color-input");
    const arrow = content.querySelector<HTMLElement>(".output-color-arrow");
    const outputSwatch = content.querySelector<HTMLElement>(".output-color-output");
    const label = content.querySelector<HTMLElement>(".output-color-label");
    if (inputSwatch !== null) {
      inputSwatch.hidden = !changed;
      inputSwatch.style.backgroundColor = rgbaToCss(before);
    }
    if (arrow !== null) {
      arrow.hidden = !changed;
    }
    if (outputSwatch !== null) {
      outputSwatch.style.backgroundColor = rgbaToCss(after);
    }
    if (label !== null) {
      label.textContent = rgbaToCompactLabel(after);
    }
    cell.className = changed
      ? "output-value-color output-value-changed"
      : "output-value-color";
    const outputText = formatOutputValue(after);
    cell.title = changed
      ? `Input: ${formatOutputValue(before)}\nOutput: ${outputText}`
      : outputText;
  }
}
