import type { CtxCameraData, CtxCharacterData, CtxGlobalData, CtxPartData } from "./ctxBindings";
import { flattenPath } from "./parts";
import type { LocalRect, NaturalCharacter, PartGeometry } from "./sceneGeometry";

export interface Point3D {
  x: number;
  y: number;
  z: number;
}

export interface ProjectedPartGeometry {
  pathData?: string;
  clipPathData?: string;
  boxPathData: string;
  depth: number;
}

const kDegreesToRadians = Math.PI / 180;
const kNearEpsilonRatio = 0.001;
const kProjectionCurveSegments = 8;

export class Projection3DProjector {
  private readonly camera: OrbitCamera;

  constructor(
    private readonly canvasWidth: number,
    private readonly canvasHeight: number,
    private readonly global: CtxGlobalData,
    camera: CtxCameraData,
  ) {
    this.camera = new OrbitCamera(canvasWidth, canvasHeight, camera);
  }

  projectPart(
    natural: NaturalCharacter,
    geometry: PartGeometry,
    character: CtxCharacterData,
    part: CtxPartData,
  ): ProjectedPartGeometry {
    const projectLocalPoint = (x: number, y: number): ProjectedPoint =>
      this.projectPoint(
        { x: x + natural.centerX, y: y + natural.centerY, z: part.z * this.canvasHeight },
        natural,
        geometry,
        character,
        part,
      );
    const projectedPath = geometry.pathData === undefined
      ? undefined
      : flattenPath(geometry.pathData, kProjectionCurveSegments)
        .map((subpath) => pathFromPoints(subpath.points.map((point) => projectLocalPoint(point.x, point.y)), subpath.closed))
        .join("");
    const clipPathData = geometry.clipRect === undefined
      ? undefined
      : this.projectRectangle(geometry.clipRect, projectLocalPoint);
    const boxPathData = this.projectRectangle({
      x: geometry.centerX - natural.centerX - geometry.width / 2,
      y: geometry.centerY - natural.centerY - geometry.height / 2,
      width: geometry.width,
      height: geometry.height,
    }, projectLocalPoint);
    const center = this.projectPoint(
      { x: geometry.centerX, y: geometry.centerY, z: part.z * this.canvasHeight },
      natural,
      geometry,
      character,
      part,
    );
    return { pathData: projectedPath, clipPathData, boxPathData, depth: center.depth };
  }

  projectCharacterCenter(
    natural: NaturalCharacter,
    character: CtxCharacterData,
  ): { x: number; y: number; depth: number } {
    const pointAfterCharacter = applyCharacterTransform(
      { x: natural.boundingCenterX, y: natural.boundingCenterY, z: 0 },
      natural,
      character,
      this.canvasWidth,
      this.canvasHeight,
    );
    return this.camera.project(applyGlobalTransform(
      pointAfterCharacter,
      this.global,
      this.canvasWidth,
      this.canvasHeight,
    ));
  }

  private projectRectangle(
    rectangle: LocalRect,
    projectPoint: (x: number, y: number) => ProjectedPoint,
  ): string {
    return pathFromPoints([
      projectPoint(rectangle.x, rectangle.y),
      projectPoint(rectangle.x + rectangle.width, rectangle.y),
      projectPoint(rectangle.x + rectangle.width, rectangle.y + rectangle.height),
      projectPoint(rectangle.x, rectangle.y + rectangle.height),
    ], true);
  }

  private projectPoint(
    point: Point3D,
    natural: NaturalCharacter,
    geometry: PartGeometry,
    character: CtxCharacterData,
    part: CtxPartData,
  ): ProjectedPoint {
    const pointAfterPart = applyPartTransform(
      point,
      geometry,
      part,
      this.canvasWidth,
      this.canvasHeight,
    );
    const pointAfterCharacter = applyCharacterTransform(
      pointAfterPart,
      natural,
      character,
      this.canvasWidth,
      this.canvasHeight,
    );
    return this.camera.project(applyGlobalTransform(
      pointAfterCharacter,
      this.global,
      this.canvasWidth,
      this.canvasHeight,
    ));
  }
}

interface ProjectedPoint {
  x: number;
  y: number;
  depth: number;
}

class OrbitCamera {
  private readonly cameraPosition: Point3D;
  private readonly screenCenterX: number;
  private readonly screenCenterY: number;
  private readonly focalLength: number;
  private readonly yaw: number;
  private readonly pitch: number;
  private readonly nearEpsilon: number;

  constructor(canvasWidth: number, canvasHeight: number, camera: CtxCameraData) {
    this.yaw = camera.yaw * kDegreesToRadians;
    this.pitch = camera.pitch * kDegreesToRadians;
    const target = {
      x: canvasWidth * camera.target_x,
      y: canvasHeight * (1 - camera.target_y),
      z: 0,
    };
    const distanceFactor = perspectiveToDistance(camera.perspective);
    const distance = distanceFactor * canvasHeight;
    const direction = rotateYawPitch({ x: 0, y: 0, z: 1 }, this.yaw, this.pitch);
    this.cameraPosition = {
      x: target.x - distance * direction.x,
      y: target.y - distance * direction.y,
      z: target.z - distance * direction.z,
    };
    this.screenCenterX = canvasWidth * (0.5 + camera.lens_shift_x);
    this.screenCenterY = canvasHeight * (0.5 - camera.lens_shift_y);
    this.focalLength = distanceFactor * camera.zoom * canvasHeight;
    this.nearEpsilon = kNearEpsilonRatio * canvasHeight;
  }

  project(worldPoint: Point3D): ProjectedPoint {
    const relative = {
      x: worldPoint.x - this.cameraPosition.x,
      y: worldPoint.y - this.cameraPosition.y,
      z: worldPoint.z - this.cameraPosition.z,
    };
    const view = inverseRotateYawPitch(relative, this.yaw, this.pitch);
    const safeDepth = Math.max(view.z, this.nearEpsilon);
    return {
      x: this.screenCenterX + this.focalLength * view.x / safeDepth,
      y: this.screenCenterY + this.focalLength * view.y / safeDepth,
      depth: view.z,
    };
  }
}

export function perspectiveToDistance(perspective: number): number {
  let inverseDistance = 0.5;
  if (perspective <= 0.5) {
    inverseDistance = 0.1 + 0.4 * (perspective / 0.5);
  } else {
    inverseDistance = 0.5 + 4.5 * ((perspective - 0.5) / 0.5);
  }
  return 1 / inverseDistance;
}

function applyPartTransform(
  point: Point3D,
  geometry: PartGeometry,
  part: CtxPartData,
  canvasWidth: number,
  canvasHeight: number,
): Point3D {
  const anchor = {
    x: geometry.centerX + (part.pivot_x - 0.5) * canvasWidth,
    y: geometry.centerY - (part.pivot_y - 0.5) * canvasHeight,
  };
  let result = {
    x: (point.x - anchor.x) * part.scale * part.stretch_x,
    y: (point.y - anchor.y) * part.scale * part.stretch_y,
    z: point.z,
  };
  result = rotateYawPitch(result, part.yaw * kDegreesToRadians, part.pitch * kDegreesToRadians);
  result = rotateZ(result, part.rotation * kDegreesToRadians);
  return {
    x: result.x + anchor.x + (part.offset_x - 0.5) * canvasWidth,
    y: result.y + anchor.y - (part.offset_y - 0.5) * canvasHeight,
    z: result.z,
  };
}

function applyCharacterTransform(
  point: Point3D,
  natural: NaturalCharacter,
  character: CtxCharacterData,
  canvasWidth: number,
  canvasHeight: number,
): Point3D {
  const anchor = {
    x: natural.boundingCenterX + (character.pivot_x - 0.5) * canvasWidth,
    y: natural.boundingCenterY - (character.pivot_y - 0.5) * canvasHeight,
  };
  let result = {
    x: (point.x - anchor.x) * character.scale * character.stretch_x,
    y: (point.y - anchor.y) * character.scale * character.stretch_y,
    z: point.z,
  };
  result = rotateYawPitch(result, character.yaw * kDegreesToRadians, character.pitch * kDegreesToRadians);
  result = rotateZ(result, character.rotation * kDegreesToRadians);
  return {
    x: result.x + anchor.x + (character.offset_x - 0.5) * canvasWidth,
    y: result.y + anchor.y - (character.offset_y - 0.5) * canvasHeight,
    z: result.z + character.z * canvasHeight,
  };
}

function applyGlobalTransform(
  point: Point3D,
  global: CtxGlobalData,
  canvasWidth: number,
  canvasHeight: number,
): Point3D {
  const pivot = {
    x: (global.pivot_x - 0.5) * canvasWidth,
    y: -(global.pivot_y - 0.5) * canvasHeight,
  };
  let result = {
    x: (point.x - pivot.x) * global.scale * global.stretch_x,
    y: (point.y - pivot.y) * global.scale * global.stretch_y,
    z: point.z,
  };
  result = rotateYawPitch(result, global.yaw * kDegreesToRadians, global.pitch * kDegreesToRadians);
  result = rotateZ(result, global.rotation * kDegreesToRadians);
  return {
    x: result.x + pivot.x + global.position_x * canvasWidth,
    y: result.y + pivot.y + (1 - global.position_y) * canvasHeight,
    z: result.z,
  };
}

function rotateYawPitch(point: Point3D, yaw: number, pitch: number): Point3D {
  const cosineYaw = Math.cos(yaw);
  const sineYaw = Math.sin(yaw);
  const cosinePitch = Math.cos(pitch);
  const sinePitch = Math.sin(pitch);
  return {
    x: cosineYaw * point.x + sineYaw * sinePitch * point.y - sineYaw * cosinePitch * point.z,
    y: cosinePitch * point.y + sinePitch * point.z,
    z: sineYaw * point.x - cosineYaw * sinePitch * point.y + cosineYaw * cosinePitch * point.z,
  };
}

function inverseRotateYawPitch(point: Point3D, yaw: number, pitch: number): Point3D {
  const cosineYaw = Math.cos(yaw);
  const sineYaw = Math.sin(yaw);
  const cosinePitch = Math.cos(pitch);
  const sinePitch = Math.sin(pitch);
  return {
    x: cosineYaw * point.x + sineYaw * point.z,
    y: sineYaw * sinePitch * point.x + cosinePitch * point.y - cosineYaw * sinePitch * point.z,
    z: -sineYaw * cosinePitch * point.x + sinePitch * point.y + cosineYaw * cosinePitch * point.z,
  };
}

function rotateZ(point: Point3D, angle: number): Point3D {
  const cosine = Math.cos(angle);
  const sine = Math.sin(angle);
  return {
    x: cosine * point.x - sine * point.y,
    y: sine * point.x + cosine * point.y,
    z: point.z,
  };
}

function pathFromPoints(points: readonly ProjectedPoint[], closed: boolean): string {
  let result = "";
  if (points.length > 0) {
    result = `M${points[0].x},${points[0].y}`;
    for (const point of points.slice(1)) {
      result += `L${point.x},${point.y}`;
    }
    if (closed) {
      result += "Z";
    }
  }
  return result;
}
