// Generic trailing-edge debouncer: calls `callback` at most once per
// `delayMilliseconds`, using the arguments of the most recent call. Shared by
// the VSCode document watcher and the web build's editor model watcher, both
// of which need to batch rapid keystrokes before reloading the simulator.

export interface Debounced<Args extends unknown[]> {
  call(...args: Args): void;
  cancel(): void;
}

export function createDebouncer<Args extends unknown[]>(
  callback: (...args: Args) => void,
  delayMilliseconds: number,
): Debounced<Args> {
  let timer: ReturnType<typeof setTimeout> | undefined;

  return {
    call(...args: Args): void {
      if (timer !== undefined) {
        clearTimeout(timer);
      }
      timer = setTimeout(() => {
        timer = undefined;
        callback(...args);
      }, delayMilliseconds);
    },
    cancel(): void {
      if (timer !== undefined) {
        clearTimeout(timer);
        timer = undefined;
      }
    },
  };
}
