// Orchestrates one simulated frame:
//   seed -> OnPreLayout -> layout (HarfBuzz shaping when a font is loaded,
//   fixed-advance boxes otherwise) -> part approximation -> seed -> OnLayout
//   -> composed transforms ready for the canvas renderer.

import {
  BaseHookData,
  CtxCameraData,
  CtxBoundingBoxData,
  CtxCharacterData,
  CtxGlobalData,
  CtxMetaData,
  CtxPartData,
  CtxOutputData,
  InitializeHookData,
  LayoutHookData,
  cameraToCtx,
  boundingBoxToCtx,
  characterSceneToCtx,
  ctxToGlobal,
  globalToCtx,
  partSceneToCtx,
  outputToCtx,
} from "./ctxBindings";
import type { ScriptEngine } from "./luaEngine";
import type { TextLayoutEngine } from "./layout";
import {
  createDefaultCharacterScene,
  createDefaultPartScene,
  type GlobalScene,
  type Rgba,
  type Scene,
} from "../shared/sceneSchema";
import { Mat2D, multiply } from "./transform";
import { resolveEffectiveCharacter, resolveEffectivePart } from "./effectiveParameters";
import { ScriptFramePipeline, type PathHookData } from "./scriptFramePipeline";
import {
  SceneGeometry,
  characterMatrix,
  globalMatrix,
  partMatrix,
  type LocalRect,
} from "./sceneGeometry";
import { fontSizePixels, shadowOffsetPixels } from "./renderUnits";
import { Projection3DProjector } from "./projection3D";
import { kPluginVersion, kScriptApiLevel } from "../shared/scriptingApi";

export interface EvaluatedBox {
  index: number;
  centerX: number;
  centerY: number;
  width: number;
  height: number;
  matrix: Mat2D;
  fillColor: Rgba;
  // Resolved global*character*part opacity multiplier applied on top of fillColor/strokeColor/
  // shadowColor's own alpha at draw time.
  opacity: number;
  useGradientFill: boolean;
  strokeWidth: number;
  strokeGap: number;
  strokeColor: Rgba;
  shadowColor: Rgba;
  // Mirrors Native's resolved useIndividualShadowColor_: true when this box (or, for a part, its
  // owning character) opted into an individual shadow color. The shadow pass draws a box when this
  // is true even while the global shadow is off (frame.shadowEnabled false), matching how Native's
  // shadow pass is gated per box instead of by the global toggle alone.
  hasIndividualShadow: boolean;
  characterIndex: number;
  text?: string;
  // True when the source character is whitespace without a glyph outline;
  // such parts follow the show-spaces display setting.
  isSpace?: boolean;
  // Character-center-relative outline (present when a font is loaded). The
  // renderer translates by (originX, originY) before filling.
  pathData?: string;
  originX?: number;
  originY?: number;
  // Present in fixed part mode: the slice of the outline this part draws.
  clipRect?: LocalRect;
  // Canvas-space paths produced by the lightweight perspective projector.
  projectedPathData?: string;
  projectedClipPathData?: string;
  projectedBoxPathData?: string;
  projectionDepth?: number;
  projectedCenterX?: number;
  projectedCenterY?: number;
}

export interface EvaluatedGradient {
  enabled: boolean;
  startColor: Rgba;
  endColor: Rgba;
  midpoint: number;
  angle: number;
  start: number;
  end: number;
}

export interface EvaluatedFrame {
  frame: number;
  time: number;
  canvasWidth: number;
  canvasHeight: number;
  backgroundColor: Rgba;
  checkerboardBackground: boolean;
  showSpaces: boolean;
  spaceColor: Rgba;
  shadowEnabled: boolean;
  shadowOffsetX: number;
  shadowOffsetY: number;
  gradient: EvaluatedGradient;
  projection3D: boolean;
  characters: EvaluatedBox[];
  parts: EvaluatedBox[];
  scriptInputValues: EvaluatedParameterValues;
  scriptOutputValues: EvaluatedParameterValues;
  requestedFontName?: string;
  errors: string[];
  warnings: string[];
}

export interface EvaluatedParameterValues {
  global: CtxGlobalData;
  camera: CtxCameraData;
  characters: CtxCharacterData[];
  parts: CtxPartData[];
  boundingBox: CtxBoundingBoxData;
  output: CtxOutputData;
}

export interface SceneTopology {
  characterCount: number;
  partCount: number;
}

const kFrameSeedMultiplier = 2654435761;
const kMaximumCharacters = 128;
const kMaximumParts = 512;
// The simulator previews a single instance, so ctx.meta.instance_seed is a fixed value rather than
// one derived from a host instance ID (see ScriptStage::mixInstanceSeed on the plugin side).
const kSimulatorInstanceSeed = 0x1a2b3c4d;

function frameSeed(frame: number, hookIndex: number): number {
  return ((Math.imul(Math.floor(frame), kFrameSeedMultiplier) + hookIndex) >>> 0) % 0x7fffffff;
}

function createCtxMeta(scene: Scene): CtxMetaData {
  return {
    api_level: kScriptApiLevel,
    plugin_version: kPluginVersion,
    capabilities: {
      has_3d: scene.settings.projection3D,
    },
    limits: {
      max_characters: kMaximumCharacters,
      max_parts: kMaximumParts,
    },
    instance_seed: kSimulatorInstanceSeed,
  };
}

function createCanvas(width: number, height: number) {
  return {
    width,
    height,
    aspect_ratio: height > 0 ? width / height : 0,
    pixel_aspect_ratio: 1,
  };
}

function createTimeline(scene: Scene, frame: number) {
  const durationFrames = scene.settings.durationFrames;
  return {
    available: true,
    start_frame: 0,
    end_frame: durationFrames,
    duration_frames: durationFrames,
    duration_seconds: durationFrames / scene.settings.fps,
    progress: durationFrames > 0 ? Math.min(Math.max(frame / durationFrames, 0), 1) : 0,
  };
}

export class FrameEvaluator {
  private readonly scriptPipeline: ScriptFramePipeline;
  private readonly sceneGeometry = new SceneGeometry();
  private selectedLayoutEngine: TextLayoutEngine | undefined;
  private readonly layoutEnginesByFamily = new Map<string, TextLayoutEngine>();
  private fontNames: string[] = [];

  constructor(engine: ScriptEngine) {
    this.scriptPipeline = new ScriptFramePipeline(engine);
  }

  setLayoutEngine(layoutEngine: TextLayoutEngine | undefined): void {
    this.selectedLayoutEngine = layoutEngine;
    if (layoutEngine !== undefined) {
      this.layoutEnginesByFamily.set(layoutEngine.familyName(), layoutEngine);
    }
    this.sceneGeometry.setLayoutEngine(layoutEngine);
  }

  registerLayoutEngine(layoutEngine: TextLayoutEngine, requestedFamily?: string): void {
    this.layoutEnginesByFamily.set(layoutEngine.familyName(), layoutEngine);
    if (requestedFamily !== undefined) {
      this.layoutEnginesByFamily.set(requestedFamily, layoutEngine);
    }
  }

  setFontNames(fontNames: readonly string[]): void {
    this.fontNames = [...fontNames];
  }

  synchronizeSceneTopology(scene: Scene): SceneTopology {
    this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
    const naturalCharacters = this.sceneGeometry.layoutCharacters(scene.global, scene);
    const partGeometry = this.sceneGeometry.buildPartGeometry(naturalCharacters, scene);
    const partCount = partGeometry.reduce((sum, parts) => sum + parts.length, 0);
    while (scene.characters.length < naturalCharacters.length) {
      scene.characters.push(createDefaultCharacterScene());
    }
    while (scene.global.margins.length < naturalCharacters.length) {
      scene.global.margins.push(0);
    }
    while (scene.parts.length < partCount) {
      scene.parts.push(createDefaultPartScene());
    }
    return { characterCount: naturalCharacters.length, partCount };
  }

  // Runs OnInitialize against the current scene snapshot. Must be called
  // after every script (re)load and whenever init-relevant scene inputs
  // change; time changes must NOT trigger it.
  initialize(scene: Scene): { errors: string[]; storage?: unknown } {
    this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
    const initData: InitializeHookData = {
      canvas: createCanvas(scene.settings.canvasWidth, scene.settings.canvasHeight),
      fonts: this.fontNames,
      meta: createCtxMeta(scene),
    };
    return this.scriptPipeline.initialize(initData);
  }

  evaluate(scene: Scene, frame: number): EvaluatedFrame {
    this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
    const { canvasWidth, canvasHeight, fps } = scene.settings;
    const time = frame / fps;
    const errors: string[] = [];
    const warnings: string[] = [];

    const selectedFontName = this.selectedLayoutEngine?.familyName() ?? scene.global.fontName;
    const baseGlobal: GlobalScene = { ...scene.global, fontName: selectedFontName };
    const baseData: BaseHookData = {
      time,
      frame,
      fps,
      text: scene.global.text,
      canvas: createCanvas(canvasWidth, canvasHeight),
      fonts: this.fontNames,
      timeline: createTimeline(scene, frame),
      meta: createCtxMeta(scene),
      global: globalToCtx(baseGlobal),
      camera: cameraToCtx(scene.camera),
    };
    const baseEvaluation = this.scriptPipeline.evaluateBase(baseData, frameSeed(frame, 1));
    errors.push(...baseEvaluation.errors);
    warnings.push(...baseEvaluation.warnings);
    const resolvedGlobal = baseEvaluation.data.global;
    const resolvedGlobalScene = ctxToGlobal(resolvedGlobal);
    const resolvedCamera = baseEvaluation.data.camera;

    let requestedFontName: string | undefined;
    const resolvedLayoutEngine = this.layoutEnginesByFamily.get(resolvedGlobal.font_name);
    if (resolvedLayoutEngine !== undefined) {
      this.sceneGeometry.setLayoutEngine(resolvedLayoutEngine);
    } else {
      this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
      if (resolvedGlobal.font_name.length > 0 && resolvedGlobal.font_name !== selectedFontName) {
        requestedFontName = resolvedGlobal.font_name;
      }
    }

    const naturalCharacters = this.sceneGeometry.layoutCharacters(resolvedGlobalScene, scene);
    const partGeometry = this.sceneGeometry.buildPartGeometry(naturalCharacters, scene);
    let characterPartStart = 1;
    const characterData = naturalCharacters.map((natural, index) => {
      const characterScene = scene.characters[index] ?? createDefaultCharacterScene();
      const partCount = partGeometry[index].length;
      const character = {
        ...characterSceneToCtx(characterScene),
        index: index + 1,
        text: natural.text,
        part_start: characterPartStart,
        part_count: partCount,
        line_index: natural.lineIndex + 1,
        geometry: {
          canvas_origin_x: 0.5 + natural.originX / canvasWidth,
          canvas_origin_y: 0.5 - natural.originY / canvasHeight,
          vertical_origin_x: 0.5 + natural.verticalOriginX / canvasWidth,
          vertical_origin_y: 0.5 - natural.verticalOriginY / canvasHeight,
          bounds_center_x: 0.5 + natural.boundingCenterX / canvasWidth,
          bounds_center_y: 0.5 - natural.boundingCenterY / canvasHeight,
          bounds_width: natural.width / canvasWidth,
          bounds_height: natural.height / canvasHeight,
          advance_x: natural.advanceX / canvasWidth,
          advance_y: -natural.advanceY / canvasHeight,
        },
      };
      characterPartStart += partCount;
      return character;
    });
    let sourcePartIndex = 0;
    const partData: CtxPartData[] = partGeometry.flatMap((parts, characterIndex) =>
      parts.map((geometry, indexInCharacter) => {
        const partScene = scene.parts[sourcePartIndex] ?? createDefaultPartScene();
        const natural = naturalCharacters[characterIndex];
        const part = {
          ...partSceneToCtx(partScene),
          index: sourcePartIndex + 1,
          character_index: characterIndex + 1,
          index_in_character: indexInCharacter + 1,
          geometry: {
            local_center_x: (geometry.centerX - natural.boundingCenterX) / canvasWidth,
            local_center_y: -(geometry.centerY - natural.boundingCenterY) / canvasHeight,
            canvas_center_x: 0.5 + geometry.centerX / canvasWidth,
            canvas_center_y: 0.5 - geometry.centerY / canvasHeight,
            bounds_center_x: 0.5 + geometry.centerX / canvasWidth,
            bounds_center_y: 0.5 - geometry.centerY / canvasHeight,
            bounds_width: geometry.width / canvasWidth,
            bounds_height: geometry.height / canvasHeight,
          },
        };
        sourcePartIndex += 1;
        return part;
      }),
    );

    const layoutHookData: LayoutHookData = {
      time,
      frame,
      fps,
      text: resolvedGlobal.text,
      char_count: naturalCharacters.length,
      part_count: partData.length,
      canvas: createCanvas(canvasWidth, canvasHeight),
      fonts: this.fontNames,
      timeline: createTimeline(scene, frame),
      font: (() => {
        const metrics = this.sceneGeometry.fontMetrics(fontSizePixels(canvasHeight));
        return {
          ascent: metrics.ascent / canvasHeight,
          descent: metrics.descent / canvasHeight,
          line_height: metrics.lineHeight / canvasHeight,
          units_per_em: metrics.unitsPerEm,
        };
      })(),
      meta: createCtxMeta(scene),
      global: resolvedGlobal,
      camera: resolvedCamera,
      chars: characterData,
      parts: partData,
      bounding_box: boundingBoxToCtx(scene.boundingBox),
      output: outputToCtx(scene.output),
    };
    const layoutEvaluation = baseEvaluation.succeeded
      ? this.scriptPipeline.evaluateLayout(layoutHookData, frameSeed(frame, 2))
      : { data: layoutHookData, succeeded: false, errors: [], warnings: [] };
    errors.push(...layoutEvaluation.errors);
    warnings.push(...layoutEvaluation.warnings);
    const resolvedCharacters = layoutEvaluation.data.chars;
    const resolvedParts = layoutEvaluation.data.parts;
    const resolvedBoundingBox = layoutEvaluation.data.bounding_box;
    const resolvedOutput = layoutEvaluation.data.output;

    const flatPartGeometry = partGeometry.flat();
    const normalizedUnitsPerEm = 1000;
    const pathFontSize = fontSizePixels(canvasHeight);
    const pathHookData: PathHookData = {
      time,
      frame,
      fps,
      char_count: naturalCharacters.length,
      part_count: partData.length,
      canvas: createCanvas(canvasWidth, canvasHeight),
      fonts: this.fontNames,
      timeline: createTimeline(scene, frame),
      font: (() => {
        const metrics = this.sceneGeometry.fontMetrics(pathFontSize);
        return {
          ascent: metrics.ascent / canvasHeight,
          descent: metrics.descent / canvasHeight,
          line_height: metrics.lineHeight / canvasHeight,
          units_per_em: metrics.unitsPerEm,
        };
      })(),
      meta: createCtxMeta(scene),
      global: layoutEvaluation.data.global,
      camera: layoutEvaluation.data.camera,
      chars: layoutEvaluation.data.chars,
      parts: layoutEvaluation.data.parts,
      bounding_box: layoutEvaluation.data.bounding_box,
      output: layoutEvaluation.data.output,
      path_parts: partData.map((_part, partIndex) => {
        const part = partData[partIndex];
        const characterIndex = part.character_index ?? 1;
        const character = characterData[characterIndex - 1];
        return {
          index: part.index ?? partIndex + 1,
          character_index: characterIndex,
          index_in_character: part.index_in_character ?? 1,
          line_index: character.line_index ?? 1,
          text: character.text ?? "",
          path: {
            svg: scaleSvgPathNumbers(
              flatPartGeometry[partIndex]?.pathData ?? "",
              normalizedUnitsPerEm / pathFontSize,
            ),
            units_per_em: normalizedUnitsPerEm,
          },
        };
      }),
    };
    const pathEvaluation =
      baseEvaluation.succeeded && layoutEvaluation.succeeded
        ? this.scriptPipeline.evaluatePaths(pathHookData, frameSeed(frame, 3))
        : { data: pathHookData, succeeded: true, errors: [], warnings: [] };
    errors.push(...pathEvaluation.errors);
    warnings.push(...pathEvaluation.warnings);
    const pathOverrides = new Map(
      pathEvaluation.data.path_parts
        .filter((part) => part.edited === true)
        .map((part) => [
          part.index - 1,
          part.path.view_box === undefined
            ? scaleSvgPathNumbers(part.path.svg, pathFontSize / part.path.units_per_em)
            : scaleSvgPathNumbers(
              normalizeSvgPathViewBox(
                part.path.svg,
                part.path.view_box,
                normalizedUnitsPerEm,
                part.path.em_scale ?? 1,
              ),
              pathFontSize / normalizedUnitsPerEm,
            ),
        ]),
    );

    const scriptOutputCharacters = naturalCharacters.map(
      (_, index) => resolvedCharacters[index] ?? characterData[index],
    );
    const scriptOutputParts = partData.map(
      (input, index) => resolvedParts[index] ?? input,
    );
    const effectiveCharacters = naturalCharacters.map((_, index) =>
      resolveEffectiveCharacter(scriptOutputCharacters[index], resolvedGlobal),
    );

    const shadowOffset = shadowOffsetPixels(
      resolvedGlobal.shadow.distance,
      resolvedGlobal.shadow.angle,
      canvasWidth,
      canvasHeight,
    );

    const globalTransform = globalMatrix(resolvedGlobal, canvasWidth, canvasHeight);
    const projector = scene.settings.projection3D
      ? new Projection3DProjector(canvasWidth, canvasHeight, resolvedGlobal, resolvedCamera)
      : undefined;
    const characters: EvaluatedBox[] = [];
    const parts: EvaluatedBox[] = [];
    const effectiveParts: CtxPartData[] = [];
    let flatPartIndex = 0;
    for (const [index, natural] of naturalCharacters.entries()) {
      const character = effectiveCharacters[index];
      const characterTransform = multiply(
        globalTransform,
        characterMatrix(character, natural, canvasWidth, canvasHeight),
      );
      const projectedCharacterCenter = projector?.projectCharacterCenter(natural, character);
      const isSpaceCharacter =
        natural.pathData === undefined && natural.text.trim().length === 0;
      characters.push({
        index: index + 1,
        centerX: natural.centerX,
        centerY: natural.centerY,
        width: natural.width,
        height: natural.height,
        matrix: characterTransform,
        fillColor: character.fill.color,
        opacity: character.opacity,
        useGradientFill: !character.fill.use,
        strokeWidth: character.stroke.width,
        strokeGap: character.stroke.gap,
        strokeColor: character.stroke.color,
        shadowColor: character.shadow.color,
        hasIndividualShadow: character.shadow.use,
        characterIndex: index + 1,
        text: natural.text,
        pathData: natural.pathData,
        originX: natural.centerX,
        originY: natural.centerY,
        projectionDepth: projectedCharacterCenter?.depth,
        projectedCenterX: projectedCharacterCenter?.x,
        projectedCenterY: projectedCharacterCenter?.y,
      });
      for (const geometry of partGeometry[index]) {
        const partOutput = scriptOutputParts[flatPartIndex];
        const part = resolveEffectivePart(partOutput, character);
        const scriptedPathData = pathOverrides.get(flatPartIndex);
        const drawableGeometry =
          scriptedPathData === undefined ? geometry : { ...geometry, pathData: scriptedPathData };
        const projectedGeometry = projector?.projectPart(natural, drawableGeometry, character, part);
        effectiveParts.push(part);
        parts.push({
          index: flatPartIndex + 1,
          centerX: geometry.centerX,
          centerY: geometry.centerY,
          width: geometry.width,
          height: geometry.height,
          matrix: multiply(
            characterTransform,
            // Part paths are character-center-relative and translated to the
            // character's natural center by the renderer. Therefore the
            // matrix pivot lives at the absolute part BB center in the same
            // pre-character canvas space.
            partMatrix(
              part,
              geometry.centerX,
              geometry.centerY,
              canvasWidth,
              canvasHeight,
            ),
          ),
          fillColor: part.fill.color,
          opacity: part.opacity,
          useGradientFill: !character.fill.use && !part.fill.use,
          strokeWidth: part.stroke.width,
          strokeGap: part.stroke.gap,
          strokeColor: part.stroke.color,
          shadowColor: part.shadow.color,
          hasIndividualShadow: part.shadow.use,
          characterIndex: index + 1,
          isSpace: isSpaceCharacter,
          pathData: drawableGeometry.pathData,
          originX: natural.centerX,
          originY: natural.centerY,
          clipRect: geometry.clipRect,
          projectedPathData: projectedGeometry?.pathData,
          projectedClipPathData: projectedGeometry?.clipPathData,
          projectedBoxPathData: projectedGeometry?.boxPathData,
          projectionDepth: projectedCharacterCenter?.depth ?? projectedGeometry?.depth,
        });
        flatPartIndex += 1;
      }
    }

    const result: EvaluatedFrame = {
      frame,
      time,
      canvasWidth,
      canvasHeight,
      backgroundColor: cloneColor(scene.settings.backgroundColor),
      checkerboardBackground: scene.settings.checkerboardBackground,
      showSpaces: scene.settings.showSpaces,
      spaceColor: cloneColor(scene.settings.spaceColor),
      shadowEnabled: resolvedGlobal.shadow.enabled,
      shadowOffsetX: shadowOffset.x,
      shadowOffsetY: shadowOffset.y,
      gradient: {
        enabled: resolvedGlobal.gradient.color_space !== "none",
        startColor: cloneColor(resolvedGlobal.fill.color),
        endColor: cloneColor(resolvedGlobal.gradient.end_color),
        midpoint: resolvedGlobal.gradient.midpoint,
        angle: resolvedGlobal.gradient.angle,
        start: resolvedGlobal.gradient.start_position,
        end: resolvedGlobal.gradient.end_position,
      },
      projection3D: scene.settings.projection3D,
      characters,
      parts,
      scriptInputValues: {
        global: globalToCtx(baseGlobal),
        camera: cameraToCtx(scene.camera),
        characters: characterData,
        parts: partData,
        boundingBox: boundingBoxToCtx(scene.boundingBox),
        output: outputToCtx(scene.output),
      },
      scriptOutputValues: {
        global: resolvedGlobal,
        camera: resolvedCamera,
        characters: scriptOutputCharacters,
        parts: scriptOutputParts,
        boundingBox: resolvedBoundingBox,
        output: resolvedOutput,
      },
      requestedFontName,
      errors,
      warnings,
    };
    this.sceneGeometry.setLayoutEngine(this.selectedLayoutEngine);
    return result;
  }

}

function cloneColor(color: Rgba): Rgba {
  return { r: color.r, g: color.g, b: color.b, a: color.a };
}

function scaleSvgPathNumbers(pathData: string, scale: number): string {
  const numberPattern = /[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/g;
  return pathData.replace(
    numberPattern,
    (value) => String(Number((Number(value) * scale).toPrecision(12))),
  );
}

// Mirrors readSvgPathNormalization in ScriptPathBindings.cc: the view box is centred on the origin
// and its longest side maps to em_scale ems, so em_scale 1.0 fills exactly one em.
function normalizeSvgPathViewBox(
  pathData: string,
  viewBox: number[],
  normalizedSize: number,
  emScale: number,
): string {
  const [minimumX, minimumY, width, height] = viewBox;
  const centerX = minimumX + width * 0.5;
  const centerY = minimumY + height * 0.5;
  const scale = (normalizedSize * emScale) / Math.max(width, height);
  const commandPattern = /([MmLlHhVvQqTtCcSsZz])([^MmLlHhVvQqTtCcSsZz]*)/g;
  const numberPattern = /[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/g;
  let firstCommand = true;
  return [...pathData.matchAll(commandPattern)].map((match) => {
    const command = match[1];
    const values = (match[2].match(numberPattern) ?? []).map(Number);
    const absolute = command === command.toUpperCase();
    const horizontal = command.toUpperCase() === "H";
    const vertical = command.toUpperCase() === "V";
    const transformed = values.map((value, index) => {
      let result = value * scale;
      if (absolute || (firstCommand && command === "m" && index < 2)) {
        const coordinateCenter = horizontal || (!vertical && index % 2 === 0) ? centerX : centerY;
        result = (value - coordinateCenter) * scale;
      }
      return String(Number(result.toPrecision(12)));
    });
    firstCommand = false;
    return command + (transformed.length > 0 ? ` ${transformed.join(" ")}` : "");
  }).join(" ");
}
