// Text layout on top of HarfBuzz shaping: one shaping pass per line, then
// tracking / line spacing / alignment / vertical flow applied to the shaped
// result. Coordinates are canvas pixels, y-down; glyph path data comes out of
// HarfBuzz already y-down and scaled to the requested font size.
//
// The harfbuzzjs module is injected (typeof import("harfbuzzjs")) because it
// is loaded differently per environment: dynamic import of a bundled asset in
// the webview, a regular node import in tests.

import type * as HarfBuzz from "harfbuzzjs";
import type { GlobalScene } from "../shared/sceneSchema";

export type HarfBuzzApi = typeof HarfBuzz;

export interface ShapedGlyph {
  // Path in canvas pixels, y-down, origin at the character center.
  pathData: string;
  glyphId: number;
}

export interface ShapedCharacter {
  text: string;
  lineIndex: number;
  originX: number;
  originY: number;
  verticalOriginX: number;
  verticalOriginY: number;
  advanceX: number;
  advanceY: number;
  centerX: number;
  centerY: number;
  width: number;
  height: number;
  glyphs: ShapedGlyph[];
}

export interface LayoutFrame {
  canvasWidth: number;
  canvasHeight: number;
  fontSize: number;
}

export interface FontMetrics {
  ascent: number;
  descent: number;
  lineHeight: number;
  unitsPerEm: number;
}

// Cell metrics as a fraction of font size; the baseline sits kAscentRatio
// below the cell top in horizontal flow.
const kAscentRatio = 0.8;
const kLineAdvanceRatio = 1.2;

interface ClusterGroup {
  text: string;
  glyphs: Array<HarfBuzz.GlyphInfo & Partial<HarfBuzz.GlyphPosition>>;
}

export class TextLayoutEngine {
  private readonly blob: HarfBuzz.Blob;
  private readonly face: HarfBuzz.Face;
  private readonly font: HarfBuzz.Font;
  private currentScale = 0;
  private readonly pathCache = new Map<number, string>();

  constructor(
    private readonly hb: HarfBuzzApi,
    fontBytes: ArrayBuffer,
  ) {
    this.blob = new hb.Blob(fontBytes);
    this.face = new hb.Face(this.blob);
    this.font = new hb.Font(this.face);
  }

  familyName(): string {
    const preferred = this.face.getName(16, "en");
    return preferred.length > 0 ? preferred : this.face.getName(1, "en");
  }

  fontMetrics(fontSize: number): FontMetrics {
    this.applyScale(Math.max(Math.round(fontSize), 1));
    const extents = this.font.hExtents();
    return {
      ascent: extents.ascender,
      descent: -extents.descender,
      lineHeight: extents.ascender - extents.descender + extents.lineGap,
      unitsPerEm: this.face.upem,
    };
  }

  layout(inputs: GlobalScene, frame: LayoutFrame): ShapedCharacter[] {
    this.applyScale(Math.max(Math.round(frame.fontSize), 1));
    const shapedLines = inputs.text
      .split("\n")
      .map((line) => this.shapeLine(line, inputs.vertical));
    let result: ShapedCharacter[];
    if (inputs.vertical) {
      result = this.placeVertical(shapedLines, inputs);
    } else {
      result = this.placeHorizontal(shapedLines, inputs);
    }
    return result;
  }

  private applyScale(scale: number): void {
    if (scale !== this.currentScale) {
      this.font.setScale(scale, scale);
      this.currentScale = scale;
      this.pathCache.clear();
    }
  }

  private glyphPath(glyphId: number): string {
    let path = this.pathCache.get(glyphId);
    if (path === undefined) {
      path = this.font.glyphToPath(glyphId);
      this.pathCache.set(glyphId, path);
    }
    return path;
  }

  private shapeLine(line: string, vertical: boolean): ClusterGroup[] {
    const buffer = new this.hb.Buffer();
    buffer.addText(line);
    buffer.guessSegmentProperties();
    if (vertical) {
      buffer.setDirection(this.hb.Direction.TTB);
    }
    this.hb.shape(this.font, buffer);
    const glyphs = buffer.getGlyphInfosAndPositions();

    // Cluster values are UTF-16 code unit indices into `line`; group glyphs
    // by cluster and slice the source text between cluster boundaries.
    const groups: ClusterGroup[] = [];
    const boundaries = [...new Set(glyphs.map((glyph) => glyph.cluster))].sort(
      (first, second) => first - second,
    );
    for (const [index, start] of boundaries.entries()) {
      const end = index + 1 < boundaries.length ? boundaries[index + 1] : line.length;
      groups.push({
        text: line.slice(start, end),
        glyphs: glyphs.filter((glyph) => glyph.cluster === start),
      });
    }
    return groups;
  }

  private placeHorizontal(
    shapedLines: ClusterGroup[][],
    inputs: GlobalScene,
  ): ShapedCharacter[] {
    const fontSize = this.currentScale;
    const lineAdvance = fontSize * kLineAdvanceRatio * inputs.lineSpacing;
    const blockHeight = (shapedLines.length - 1) * lineAdvance + fontSize;
    const blockTop = verticalBlockStart(inputs.vAlign, blockHeight, fontSize);

    const result: ShapedCharacter[] = [];
    let characterOffset = 0;
    for (const [lineIndex, clusters] of shapedLines.entries()) {
      const lineWidth = clusters.reduce(
        (sum, cluster, index) =>
          sum + clusterAdvanceX(cluster) + characterSpacing(inputs, characterOffset + index, fontSize),
        0,
      );
      let penX = localAlignmentStart(inputs.hAlign, lineWidth);
      const cellTop = blockTop + lineIndex * lineAdvance;
      const baselineY = cellTop + fontSize * kAscentRatio;
      for (const [clusterIndex, cluster] of clusters.entries()) {
        const width = Math.max(clusterAdvanceX(cluster), fontSize * 0.1);
        const centerX = penX + width / 2;
        const centerY = cellTop + fontSize / 2;
        result.push({
          text: cluster.text,
          lineIndex,
          originX: penX,
          originY: baselineY,
          verticalOriginX: centerX,
          verticalOriginY: cellTop,
          advanceX: clusterAdvanceX(cluster),
          advanceY: fontSize,
          centerX,
          centerY,
          width,
          height: fontSize,
          glyphs: this.clusterGlyphs(cluster, penX - centerX, baselineY - centerY),
        });
        penX += clusterAdvanceX(cluster) + characterSpacing(inputs, characterOffset + clusterIndex, fontSize);
      }
      characterOffset += clusters.length;
    }
    return result;
  }

  private placeVertical(
    shapedLines: ClusterGroup[][],
    inputs: GlobalScene,
  ): ShapedCharacter[] {
    const fontSize = this.currentScale;
    const columnAdvance = fontSize * kLineAdvanceRatio * inputs.lineSpacing;
    const blockWidth = (shapedLines.length - 1) * columnAdvance + fontSize;
    const blockLeft = localAlignmentStart(inputs.hAlign, blockWidth);

    const result: ShapedCharacter[] = [];
    let characterOffset = 0;
    for (const [lineIndex, clusters] of shapedLines.entries()) {
      const columnHeight = clusters.reduce(
        (sum, cluster, index) =>
          sum + clusterAdvanceY(cluster) + characterSpacing(inputs, characterOffset + index, fontSize),
        0,
      );
      let penY = localAlignmentStart(verticalToLinear(inputs.vAlign), columnHeight);
      // Columns flow right-to-left: the first line is the rightmost column.
      const columnCenterX =
        blockLeft + (shapedLines.length - 1 - lineIndex) * columnAdvance + fontSize / 2;
      for (const [clusterIndex, cluster] of clusters.entries()) {
        const height = Math.max(clusterAdvanceY(cluster), fontSize * 0.1);
        const centerY = penY + height / 2;
        result.push({
          text: cluster.text,
          lineIndex,
          originX: columnCenterX,
          originY: penY,
          verticalOriginX: columnCenterX,
          verticalOriginY: penY,
          advanceX: fontSize,
          advanceY: clusterAdvanceY(cluster),
          centerX: columnCenterX,
          centerY,
          width: fontSize,
          height,
          // The vertical origin's x offset is relative to the baseline, which
          // runs through the column center.
          glyphs: this.clusterGlyphs(cluster, 0, penY - centerY),
        });
        penY += clusterAdvanceY(cluster) + characterSpacing(inputs, characterOffset + clusterIndex, fontSize);
      }
      characterOffset += clusters.length;
    }
    return result;
  }

  // Converts HarfBuzz glyph offsets (y-up) into character-center-relative
  // canvas offsets (y-down). (startX, startY) is the pen start relative to
  // the character center.
  private clusterGlyphs(cluster: ClusterGroup, startX: number, startY: number): ShapedGlyph[] {
    const result: ShapedGlyph[] = [];
    let penX = startX;
    let penY = startY;
    for (const glyph of cluster.glyphs) {
      const drawX = penX + (glyph.xOffset ?? 0);
      const drawY = penY - (glyph.yOffset ?? 0);
      result.push({
        pathData: mapPathToCanvas(this.glyphPath(glyph.codepoint), drawX, drawY),
        glyphId: glyph.codepoint,
      });
      penX += glyph.xAdvance ?? 0;
      penY -= glyph.yAdvance ?? 0;
    }
    return result;
  }
}

function characterSpacing(inputs: GlobalScene, characterIndex: number, fontSize: number): number {
  return (inputs.tracking + (inputs.margins[characterIndex] ?? 0)) * fontSize;
}

function clusterAdvanceX(cluster: ClusterGroup): number {
  return cluster.glyphs.reduce((sum, glyph) => sum + (glyph.xAdvance ?? 0), 0);
}

function clusterAdvanceY(cluster: ClusterGroup): number {
  return cluster.glyphs.reduce((sum, glyph) => sum + Math.abs(glyph.yAdvance ?? 0), 0);
}

function localAlignmentStart(align: "left" | "center" | "right", extent: number): number {
  let result = -extent / 2;
  if (align === "left") {
    result = 0;
  } else if (align === "right") {
    result = -extent;
  }
  return result;
}

function verticalBlockStart(
  align: "top" | "center" | "bottom" | "baseline",
  blockHeight: number,
  fontSize: number,
): number {
  let result = localAlignmentStart(verticalToLinear(align), blockHeight);
  if (align === "baseline") {
    result = -fontSize * kAscentRatio;
  }
  return result;
}

function verticalToLinear(
  align: "top" | "center" | "bottom" | "baseline",
): "left" | "center" | "right" {
  let result: "left" | "center" | "right" = "center";
  if (align === "top") {
    result = "left";
  } else if (align === "bottom") {
    result = "right";
  }
  return result;
}

// SVG allows "10-5" (minus as separator), so numbers must be extracted with a
// pattern rather than split on whitespace/commas.
const kNumberPattern = /-?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?/g;

// Rewrites an absolute-command SVG path (M/L/Q/C/Z) from HarfBuzz's y-up font
// coordinates into y-down canvas coordinates with the pen at (dx, dy):
// x' = x + dx, y' = dy - y.
function mapPathToCanvas(pathData: string, dx: number, dy: number): string {
  return pathData.replace(
    /([MLQCZ])([^MLQCZ]*)/g,
    (_full, command: string, argumentText: string) => {
      const values = (argumentText.match(kNumberPattern) ?? []).map(Number);
      let result = command;
      if (values.length > 0) {
        const mapped = values.map((value, index) => (index % 2 === 0 ? value + dx : dy - value));
        result = command + mapped.join(",");
      }
      return result;
    },
  );
}
