interface LuaDiagnosticParameter {
  name: string;
  type: string;
}

interface LuaDiagnosticFunction {
  name: string;
  parameters: LuaDiagnosticParameter[];
}

interface LuaDiagnosticField {
  name: string;
  type: string;
}

type LuaDiagnosticClasses = Map<string, LuaDiagnosticField[]>;

function luaString(value: string): string {
  return JSON.stringify(value);
}

function annotationType(annotation: string): string {
  const atomicType =
    String.raw`(?:"[^"]*"|fun\([^)]*\)(?::\s*[A-Za-z_][A-Za-z0-9_]*(?:\[\])?)?|[A-Za-z_][A-Za-z0-9_]*(?:\[\])?)`;
  const typeExpression = new RegExp(`^(${atomicType}(?:\\|${atomicType})*)`);
  return typeExpression.exec(annotation.trim())?.[1] ?? "any";
}

function parsePreludeDiagnostics(preludeSource: string): {
  functions: LuaDiagnosticFunction[];
  classes: LuaDiagnosticClasses;
} {
  const functions: LuaDiagnosticFunction[] = [];
  const classes: LuaDiagnosticClasses = new Map();
  let parameters: LuaDiagnosticParameter[] = [];
  let currentClass: string | undefined;

  for (const line of preludeSource.split(/\r?\n/)) {
    const classMatch = /^---@class\s+([A-Za-z_][A-Za-z0-9_]*)/.exec(line);
    if (classMatch !== null) {
      currentClass = classMatch[1];
      classes.set(currentClass, []);
      parameters = [];
      continue;
    }

    const fieldMatch = /^---@field\s+([A-Za-z_][A-Za-z0-9_]*)(\?)?\s+(.+)$/.exec(line);
    if (fieldMatch !== null && currentClass !== undefined) {
      const fieldType = annotationType(fieldMatch[3]);
      classes.get(currentClass)?.push({
        name: fieldMatch[1],
        type: fieldMatch[2] === "?" ? `${fieldType}|nil` : fieldType,
      });
      continue;
    }

    const parameterMatch = /^---@param\s+([A-Za-z_][A-Za-z0-9_]*)\s+(.+)$/.exec(line);
    if (parameterMatch !== null) {
      parameters.push({
        name: parameterMatch[1],
        type: annotationType(parameterMatch[2]),
      });
      currentClass = undefined;
      continue;
    }

    const functionMatch = /^function\s+(mt(?:\.[A-Za-z_][A-Za-z0-9_]*)+)\(([^)]*)\)/.exec(line);
    if (functionMatch !== null) {
      const declaredNames = functionMatch[2]
        .split(",")
        .map((name) => name.trim())
        .filter((name) => name.length > 0);
      const annotationsByName = new Map(parameters.map((parameter) => [parameter.name, parameter]));
      functions.push({
        name: functionMatch[1],
        parameters: declaredNames.map((name) => {
          const parameter = annotationsByName.get(name) ?? { name, type: "any" };
          return name === "ctx"
            ? { ...parameter, type: parameter.type.replace("table", "MtContext") }
            : parameter;
        }),
      });
      parameters = [];
      currentClass = undefined;
      continue;
    }

    if (!line.startsWith("---") && line.trim().length > 0) {
      parameters = [];
      currentClass = undefined;
    }
  }

  // MtColor is declared by the host-facing API rather than the shared
  // prelude, but prelude helpers accept it as a structural value.
  classes.set("MtColor", [
    { name: "r", type: "number" },
    { name: "g", type: "number" },
    { name: "b", type: "number" },
    { name: "a", type: "number" },
  ]);

  // The private ArcLengthPath fields are implementation details. Public
  // helpers only require this method-shaped interface.
  classes.set("MtArcLengthPath", [
    { name: "length", type: "function" },
    { name: "at_distance", type: "function" },
  ]);

  return { functions, classes };
}

function makeClassSchemas(classes: LuaDiagnosticClasses): string {
  return [...classes.entries()]
    .map(([className, fields]) => {
      const fieldEntries = fields
        .map(
          (field) =>
            `            { name = ${luaString(field.name)}, expected = ${luaString(field.type)} },`,
        )
        .join("\n");
      return `    [${luaString(className)}] = {\n${fieldEntries}\n    },`;
    })
    .join("\n");
}

function makeFunctionSchemas(functions: LuaDiagnosticFunction[]): string {
  return functions
    .filter((entry) => entry.parameters.length > 0)
    .map((entry) => {
      const parameters = entry.parameters
        .map(
          (parameter) =>
            `            { name = ${luaString(parameter.name)}, expected = ${luaString(parameter.type)} },`,
        )
        .join("\n");
      return `    {\n        name = ${luaString(entry.name)},\n        parameters = {\n${parameters}\n        },\n    },`;
    })
    .join("\n");
}

// Generates a simulator-only Lua layer from the LuaLS annotations already
// maintained beside each public prelude function. Native never loads this
// chunk, so richer diagnostics do not add render-time work to the plugin.
export function makeLuaDiagnosticsChunk(preludeSource: string): string {
  const diagnostics = parsePreludeDiagnostics(preludeSource);
  return `
local diagnosticContextPhase = __mtInternal.contextPhase
local diagnosticHookPhase = __mtInternal.activeHookPhase
local diagnosticGetMetatable = getmetatable

local diagnosticClassSchemas = {
${makeClassSchemas(diagnostics.classes)}
}

local diagnosticFunctions = {
${makeFunctionSchemas(diagnostics.functions)}
}

local function diagnosticActual(value)
    local valueType = type(value)
    local result = valueType
    if valueType == "string" then
        local maximumLength = 80
        local displayed = value
        if #displayed > maximumLength then
            displayed = string.sub(displayed, 1, maximumLength) .. "..."
        end
        result = valueType .. " (" .. string.format("%q", displayed) .. ")"
    elseif valueType == "number" or valueType == "boolean" then
        result = valueType .. " (" .. tostring(value) .. ")"
    end
    return result
end

local diagnosticType

local function diagnosticSingleType(value, expected, path, visited)
    local matches = false
    local detail = nil
    local arrayElementType = string.match(expected, "^(.-)%[%]$")
    local stringLiteral = string.match(expected, '^"(.*)"$')
    if expected == "any" then
        matches = true
    elseif expected == "nil" then
        matches = value == nil
    elseif stringLiteral ~= nil then
        matches = value == stringLiteral
    elseif expected == "integer" then
        matches = type(value) == "number" and value % 1 == 0
    elseif expected == "function" or string.sub(expected, 1, 4) == "fun(" then
        matches = type(value) == "function"
    elseif expected == "MtContext" then
        local valueMetatable = type(value) == "table" and diagnosticGetMetatable(value) or nil
        local isDerivedContext =
            type(valueMetatable) == "table" and valueMetatable.__mt_derived_context == true
        matches = diagnosticHookPhase() == nil
            or diagnosticContextPhase(value) ~= nil
            or isDerivedContext
        if not matches and type(value) == "table" then
            detail = path .. ": expected MtContext, actual table"
                .. " (the value is not a context created by MT Sim)"
        end
    elseif arrayElementType ~= nil then
        matches = type(value) == "table"
        if matches and not visited[value] then
            visited[value] = true
            for index = 1, #value do
                local elementMatches, elementDetail =
                    diagnosticType(value[index], arrayElementType, path .. "[" .. index .. "]", visited)
                if not elementMatches then
                    matches = false
                    detail = elementDetail
                    break
                end
            end
        end
    elseif diagnosticClassSchemas[expected] ~= nil then
        matches = type(value) == "table"
        if matches and not visited[value] then
            visited[value] = true
            for _, field in ipairs(diagnosticClassSchemas[expected]) do
                local fieldValue = value[field.name]
                local fieldMatches, fieldDetail =
                    diagnosticType(fieldValue, field.expected, path .. "." .. field.name, visited)
                if not fieldMatches then
                    matches = false
                    if fieldValue == nil and not string.find(field.expected, "nil", 1, true) then
                        detail = path .. "." .. field.name .. ": required member is missing"
                    else
                        detail = fieldDetail
                    end
                    break
                end
            end
        end
    else
        matches = type(value) == expected
    end
    if not matches and detail == nil then
        detail = path .. ": expected " .. expected .. ", actual " .. diagnosticActual(value)
    end
    return matches, detail
end

diagnosticType = function(value, expected, path, visited)
    local bestDetail = nil
    for alternative in string.gmatch(expected, "[^|]+") do
        local alternativeVisited = {}
        for visitedValue in pairs(visited or {}) do
            alternativeVisited[visitedValue] = true
        end
        local matches, detail =
            diagnosticSingleType(value, alternative, path, alternativeVisited)
        if matches then
            return true, nil
        end
        if bestDetail == nil or string.find(detail or "", "required member is missing", 1, true) then
            bestDetail = detail
        end
    end
    return false, bestDetail
end

local function diagnosticOwner(qualifiedName)
    local owner = _G
    local finalName = nil
    for segment in string.gmatch(qualifiedName, "[^.]+") do
        if finalName ~= nil then
            owner = owner[finalName]
        end
        finalName = segment
    end
    return owner, finalName
end

for _, diagnosticFunction in ipairs(diagnosticFunctions) do
    local owner, fieldName = diagnosticOwner(diagnosticFunction.name)
    local original = owner ~= nil and owner[fieldName] or nil
    if type(original) == "function" then
        owner[fieldName] = function(...)
            local arguments = table.pack(...)
            for index, parameter in ipairs(diagnosticFunction.parameters) do
                local matches, detail =
                    diagnosticType(arguments[index], parameter.expected, parameter.name)
                if not matches then
                    error(
                        diagnosticFunction.name .. ": invalid argument #" .. index
                        .. " '" .. parameter.name .. "'\\n"
                        .. "  expected: " .. parameter.expected .. "\\n"
                        .. "  actual:   " .. diagnosticActual(arguments[index]) .. "\\n"
                        .. "  " .. detail,
                        2)
                end
            end
            return original(...)
        end
    end
end
`;
}
